go.solution:
import "sort"

func groupAnagrams(strs []string) [][]string {
	index := map[string]int{} // sorted letters -> group number
	out := [][]string{}
	for _, s := range strs {
		b := []byte(s)
		sort.Slice(b, func(i, j int) bool { return b[i] < b[j] })
		k := string(b)
		g, ok := index[k]
		if !ok {
			g = len(out)
			index[k] = g
			out = append(out, nil)
		}
		out[g] = append(out[g], s)
	}
	return out
}

