class Solution {
public:
    vector<vector<string>> groupAnagrams(vector<string>& strs) {
        unordered_map<string, int> index;  // sorted letters -> group number
        vector<vector<string>> groups;
        for (const string& s : strs) {
            string k = s;
            sort(k.begin(), k.end());
            auto it = index.find(k);
            if (it == index.end()) {
                index[k] = groups.size();
                groups.push_back({s});
            } else {
                groups[it->second].push_back(s);
            }
        }
        return groups;
    }
};

