use std::collections::HashMap;

impl Solution {
    pub fn group_anagrams(strs: Vec<String>) -> Vec<Vec<String>> {
        let mut index: HashMap<Vec<u8>, usize> = HashMap::new(); // sorted letters -> group number
        let mut groups: Vec<Vec<String>> = Vec::new();
        for s in strs {
            let mut key = s.clone().into_bytes();
            key.sort_unstable();
            match index.get(&key) {
                Some(&g) => groups[g].push(s),
                None => {
                    index.insert(key, groups.len());
                    groups.push(vec![s]);
                }
            }
        }
        groups
    }
}

