def longest_consecutive(nums: list[int]) -> int:
    present = set(nums)
    best = 0
    for x in present:
        if x - 1 in present:
            continue  # x is inside a run, not its start
        y = x
        while y + 1 in present:
            y += 1
        best = max(best, y - x + 1)
    return best

