object Solution {
  def threeSum(nums: Array[Int]): List[List[Int]] = {
    val a = nums.sorted
    val result = scala.collection.mutable.ArrayBuffer[List[Int]]()
    for (i <- 0 until a.length - 2) {
      if (i == 0 || a(i) != a(i - 1)) { // skip a repeated first number
        var lo = i + 1
        var hi = a.length - 1
        while (lo < hi) {
          val total = a(i) + a(lo) + a(hi)
          if (total < 0) {
            lo += 1
          } else if (total > 0) {
            hi -= 1
          } else {
            result += List(a(i), a(lo), a(hi))
            lo += 1
            hi -= 1
            while (lo < hi && a(lo) == a(lo - 1)) lo += 1
            while (lo < hi && a(hi) == a(hi + 1)) hi -= 1
          }
        }
      }
    }
    result.toList
  }
}

