func maxArea(height []int) int {
	left, right := 0, len(height)-1
	best := 0
	for left < right {
		h := height[left]
		if height[right] < h {
			h = height[right]
		}
		if (right-left)*h > best {
			best = (right - left) * h
		}
		// the shorter line limits the water, so only moving it can help
		if height[left] < height[right] {
			left++
		} else {
			right--
		}
	}
	return best
}

