def min_window(s: str, t: str) -> str:
    need = {}  # need[c] > 0: still missing; <= 0: the window has enough (or extra)
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    missing = len(t)  # how many characters of t the window still lacks
    left = 0
    best_start, best_len = 0, len(s) + 1
    for right, ch in enumerate(s):
        if need.get(ch, 0) > 0:
            missing -= 1
        need[ch] = need.get(ch, 0) - 1
        if missing == 0:
            # shrink: drop characters the window has in excess
            while need[s[left]] < 0:
                need[s[left]] += 1
                left += 1
            if right - left + 1 < best_len:
                best_start, best_len = left, right - left + 1
            # drop s[left] too, so the window is invalid again and we keep sliding
            need[s[left]] += 1
            missing += 1
            left += 1
    return "" if best_len > len(s) else s[best_start : best_start + best_len]

