from collections import deque


def max_sliding_window(nums: list[int], k: int) -> list[int]:
    window = deque()  # indices, their values decreasing: the front is the window maximum
    result = []
    for i, x in enumerate(nums):
        while window and nums[window[-1]] <= x:
            window.pop()  # smaller values behind x can never be a maximum again
        window.append(i)
        if window[0] <= i - k:
            window.popleft()  # the front index slid out of the window
        if i >= k - 1:
            result.append(nums[window[0]])
    return result

