	head := 0
	result := []int{}
	for i, x := range nums {
		for len(window) > head && nums[window[len(window)-1]] <= x {
			window = window[:len(window)-1] // smaller values behind x can never be a maximum again
		}
		window = append(window, i)
		if window[head] <= i-k {
			head++ // the front index slid out of the window
		}
		if i >= k-1 {
