  def maxSlidingWindow(nums: Array[Int], k: Int): Array[Int] = {
    val window = new Array[Int](nums.length) // indices, their values decreasing: window(head) is the maximum
    var head = 0
    var tail = 0 // window holds window(head until tail)
    val result = scala.collection.mutable.ArrayBuffer[Int]()
    for (i <- 0 until nums.length) {
      while (tail > head && nums(window(tail - 1)) <= nums(i)) {
        tail -= 1 // smaller values behind nums(i) can never be a maximum again
      }
      window(tail) = i
      tail += 1
      if (window(head) <= i - k) head += 1 // the front index slid out of the window
