func largestRectangleArea(heights []int) int {
	h := append(append([]int{}, heights...), 0) // a final bar of height 0 pops everything left on the stack
	var stack []int                             // indices of bars with increasing heights
	best := 0
	for i, cur := range h {
		for len(stack) > 0 && h[stack[len(stack)-1]] >= cur {
			height := h[stack[len(stack)-1]]
			stack = stack[:len(stack)-1]
			left := -1 // first shorter bar on the left
			if len(stack) > 0 {
				left = stack[len(stack)-1]
