object Solution {
  def evalRpn(tokens: Array[String]): Int = {
    val stack = new Array[Int](tokens.length)
    var top = 0
    for (t <- tokens) {
      t match {
        case "+" | "-" | "*" | "/" =>
          val b = stack(top - 1) // the right operand is on top
          val a = stack(top - 2)
          top -= 2
          stack(top) = t match {
            case "+" => a + b
            case "-" => a - b
            case "*" => a * b
            case _   => a / b // Scala truncates toward zero
          }
          top += 1
        case _ =>
          stack(top) = t.toInt
          top += 1
      }
    }
    stack(0)
  }
}

