impl Solution {
    pub fn merge_two_lists(list1: Option<Box<ListNode>>, list2: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
        let (mut a, mut b) = (list1, list2);
        let mut dummy = ListNode::new(0); // dummy head: no special case for the first node
        let mut tail = &mut dummy;
        while a.is_some() && b.is_some() {
            // take the smaller front node out of its list and link it after tail
            let from = if a.as_ref().unwrap().val <= b.as_ref().unwrap().val { &mut a } else { &mut b };
            let mut node = from.take().unwrap();
            *from = node.next.take();
            tail.next = Some(node);
            tail = tail.next.as_mut().unwrap();
        }
        tail.next = if a.is_some() { a } else { b }; // append whatever is left
        dummy.next
    }
}

