impl Solution {
    pub fn remove_nth_from_end(head: Option<Box<ListNode>>, n: i32) -> Option<Box<ListNode>> {
        // Rust's ownership rules make a fast/slow pointer pair awkward, so count the nodes first.
        let mut dummy = Box::new(ListNode { val: 0, next: head }); // lets us remove the head like any other node
        let mut len = 0;
        let mut cur = &dummy.next;
        while let Some(node) = cur {
            len += 1;
            cur = &node.next;
        }
        let mut prev = &mut dummy;
        for _ in 0..len - n {
            prev = prev.next.as_mut().unwrap(); // stop just before the node to remove
        }
        let removed = prev.next.take().unwrap();
        prev.next = removed.next;
        dummy.next
    }
}

