class Solution {
public:
    bool hasCycle(vector<int>& head, int pos) {
        // Build real nodes from the array, then link the last one back to node pos.
        vector<CycleNode> nodes(head.size());
        if (nodes.empty()) return false;
        for (size_t i = 0; i + 1 < nodes.size(); i++) nodes[i].next = &nodes[i + 1];
        if (pos >= 0) nodes.back().next = &nodes[pos];

        CycleNode *slow = &nodes[0], *fast = &nodes[0];
        while (fast && fast->next) {
            slow = slow->next;        // one step
            fast = fast->next->next;  // two steps: it laps slow if there is a cycle
            if (slow == fast) return true;
        }
        return false;
    }
};

