impl Solution {
    pub fn has_cycle(head: Vec<i32>, pos: i32) -> bool {
        // Nodes are just indexes 0..n. `next` gives the node after i: i + 1, and the last node links back to pos.
        let n = head.len();
        if n == 0 {
            return false;
        }
        let next = |i: usize| -> Option<usize> {
            if i + 1 < n {
                Some(i + 1)
            } else if pos >= 0 {
                Some(pos as usize)
            } else {
                None
            }
        };

        let (mut slow, mut fast) = (0, 0);
        loop {
            // fast takes two steps and slow one: fast laps slow if there is a cycle
            fast = match next(fast).and_then(next) {
                Some(f) => f,
                None => return false, // fast fell off the end
            };
            slow = next(slow).unwrap();
            if slow == fast {
                return true;
            }
        }
    }
}

