  def hasCycle(head: Array[Int], pos: Int): Boolean = {
    // Build real nodes from the array, then link the last one back to node pos.
    val nodes = Array.fill(head.length)(new CycleNode)
    if (nodes.isEmpty) return false
    for (i <- 0 until nodes.length - 1) nodes(i).next = nodes(i + 1)
    if (pos >= 0) nodes(nodes.length - 1).next = nodes(pos)

    var slow = nodes(0)
    var fast = nodes(0)
    while (fast != null && fast.next != null) {
      slow = slow.next // one step
      fast = fast.next.next // two steps: it laps slow if there is a cycle
      if (slow eq fast) return true
    }
    false
  }
}

