import "math"

func maxPathSum(root *TreeNode) int {
	best := math.MinInt64
	// best sum of a path that starts at node and goes down one side
	var gain func(node *TreeNode) int
	gain = func(node *TreeNode) int {
		if node == nil {
			return 0
		}
		left, right := gain(node.Left), gain(node.Right)
		if left < 0 { // drop a negative branch
			left = 0
		}
		if right < 0 {
			right = 0
		}
		if s := node.Val + left + right; s > best { // path that bends at node
			best = s
		}
		if left > right { // only one side can continue upward
			return node.Val + left
		}
		return node.Val + right
	}
	gain(root)
	return best
}

