// kthMinHeap is a min-heap of ints for container/heap.
type kthMinHeap []int

func (h kthMinHeap) Len() int           { return len(h) }
func (h kthMinHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h kthMinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *kthMinHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *kthMinHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func findKthLargest(nums []int, k int) int {
	h := &kthMinHeap{} // holds the k largest values seen so far
	for _, x := range nums {
		heap.Push(h, x)
		if h.Len() > k {
			heap.Pop(h) // drop the smallest of the k+1
		}
	}
	return (*h)[0] // the smallest of the k largest = k-th largest
}

