import "container/heap"

// mergeItem points at one element of one list.
type mergeItem struct{ val, list, pos int }

// mergeMinHeap is a min-heap ordered by val.
type mergeMinHeap []mergeItem

func (h mergeMinHeap) Len() int           { return len(h) }
func (h mergeMinHeap) Less(i, j int) bool { return h[i].val < h[j].val }
func (h mergeMinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *mergeMinHeap) Push(x any)        { *h = append(*h, x.(mergeItem)) }
func (h *mergeMinHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func mergeKLists(lists [][]int) []int {
	h := &mergeMinHeap{} // one entry per list: its smallest unused element
	for i, lst := range lists {
		if len(lst) > 0 {
			heap.Push(h, mergeItem{lst[0], i, 0})
		}
	}
	res := []int{}
	for h.Len() > 0 {
		it := heap.Pop(h).(mergeItem)
		res = append(res, it.val)
		if it.pos+1 < len(lists[it.list]) {
			heap.Push(h, mergeItem{lists[it.list][it.pos+1], it.list, it.pos + 1})
		}
	}
	return res
}

