import "container/heap"

// intHeap is a heap of ints; less decides which end is on top.
type intHeap struct {
	a    []int
	less func(x, y int) bool
}

func (h intHeap) Len() int            { return len(h.a) }
func (h intHeap) Less(i, j int) bool  { return h.less(h.a[i], h.a[j]) }
func (h intHeap) Swap(i, j int)       { h.a[i], h.a[j] = h.a[j], h.a[i] }
func (h *intHeap) Push(x any)         { h.a = append(h.a, x.(int)) }
func (h *intHeap) Pop() any           { x := h.a[len(h.a)-1]; h.a = h.a[:len(h.a)-1]; return x }

type MedianFinder struct {
	lo *intHeap // the smaller half, largest on top
	hi *intHeap // the larger half, smallest on top
}

func Constructor() MedianFinder {
	return MedianFinder{
		lo: &intHeap{less: func(x, y int) bool { return x > y }},
		hi: &intHeap{less: func(x, y int) bool { return x < y }},
	}
}

func (this *MedianFinder) AddNum(num int) {
	heap.Push(this.lo, num)
	heap.Push(this.hi, heap.Pop(this.lo))
	if this.hi.Len() > this.lo.Len() {
		heap.Push(this.lo, heap.Pop(this.hi))
	}
}

func (this *MedianFinder) FindMedian() float64 {
	if this.lo.Len() > this.hi.Len() {
		return float64(this.lo.a[0])
	}
	return float64(this.lo.a[0]+this.hi.a[0]) / 2
}

