def combination_sum(candidates: list[int], target: int) -> list[list[int]]:
    candidates = sorted(candidates)  # lets us stop early
    res = []
    path = []

    def dfs(start: int, remaining: int) -> None:
        if remaining == 0:
            res.append(path[:])
            return
        for i in range(start, len(candidates)):
            if candidates[i] > remaining:
                break  # all later candidates are bigger
            path.append(candidates[i])
            dfs(i, remaining - candidates[i])  # same index: a number can be reused
            path.pop()

    dfs(0, target)
