// reachFromBorder marks the cells that water can flow from, going uphill (or level) from the starts.
func reachFromBorder(heights [][]int, starts [][2]int) [][]bool {
	rows, cols := len(heights), len(heights[0])
	seen := make([][]bool, rows)
	for i := range seen {
		seen[i] = make([]bool, cols)
	}
	for _, s := range starts {
		seen[s[0]][s[1]] = true
	}
	stack := append([][2]int{}, starts...)
	dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	for len(stack) > 0 {
		cell := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, d := range dirs {
			nr, nc := cell[0]+d[0], cell[1]+d[1]
			if nr >= 0 && nc >= 0 && nr < rows && nc < cols && !seen[nr][nc] &&
				heights[nr][nc] >= heights[cell[0]][cell[1]] {
				seen[nr][nc] = true
				stack = append(stack, [2]int{nr, nc})
			}
		}
	}
	return seen
}

func pacificAtlantic(heights [][]int) [][]int {
	rows, cols := len(heights), len(heights[0])
	pacific := [][2]int{}
	atlantic := [][2]int{}
	for r := 0; r < rows; r++ {
		pacific = append(pacific, [2]int{r, 0})
		atlantic = append(atlantic, [2]int{r, cols - 1})
	}
	for c := 0; c < cols; c++ {
		pacific = append(pacific, [2]int{0, c})
		atlantic = append(atlantic, [2]int{rows - 1, c})
	}
	pac, atl := reachFromBorder(heights, pacific), reachFromBorder(heights, atlantic)
	res := [][]int{}
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if pac[r][c] && atl[r][c] {
				res = append(res, []int{r, c})
			}
		}
	}
	return res
}

