// Cells that water can flow from, going uphill (or level) from the starts.
fn reach_from_border(heights: &Vec<Vec<i32>>, starts: &[(usize, usize)]) -> Vec<Vec<bool>> {
    let (rows, cols) = (heights.len() as i32, heights[0].len() as i32);
    let mut seen = vec![vec![false; cols as usize]; rows as usize];
    for &(r, c) in starts {
        seen[r][c] = true;
    }
    let mut stack: Vec<(usize, usize)> = starts.to_vec();
    while let Some((r, c)) = stack.pop() {
        for (dr, dc) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let (nr, nc) = (r as i32 + dr, c as i32 + dc);
            if nr < 0 || nc < 0 || nr >= rows || nc >= cols {
                continue;
            }
            let (nr, nc) = (nr as usize, nc as usize);
            if !seen[nr][nc] && heights[nr][nc] >= heights[r][c] {
                seen[nr][nc] = true;
                stack.push((nr, nc));
            }
        }
    }
    seen
}

impl Solution {
    pub fn pacific_atlantic(heights: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
        let (rows, cols) = (heights.len(), heights[0].len());
        let mut pacific = Vec::new();
        let mut atlantic = Vec::new();
        for r in 0..rows {
            pacific.push((r, 0));
            atlantic.push((r, cols - 1));
        }
        for c in 0..cols {
            pacific.push((0, c));
            atlantic.push((rows - 1, c));
        }
        let pac = reach_from_border(&heights, &pacific);
        let atl = reach_from_border(&heights, &atlantic);
        let mut res = Vec::new();
        for r in 0..rows {
            for c in 0..cols {
                if pac[r][c] && atl[r][c] {
                    res.push(vec![r as i32, c as i32]);
                }
            }
        }
        res
    }
}

