	words := map[string]bool{} // words not visited yet
	for _, w := range wordList {
		words[w] = true
	}
	if !words[endWord] {
		return 0
	}
	delete(words, beginWord)
	queue := []string{beginWord}
	steps := 1
	for len(queue) > 0 {
		next := []string{} // one BFS level = one more word in the ladder
		for _, word := range queue {
			if word == endWord {
				return steps
			}
			letters := []byte(word)
			for i := range letters {
				orig := letters[i]
				for ch := byte('a'); ch <= 'z'; ch++ {
					letters[i] = ch
					candidate := string(letters)
					if words[candidate] {
						delete(words, candidate) // mark visited
						next = append(next, candidate)
					}
				}
				letters[i] = orig
			}
		}
		queue = next
		steps++
	}
	return 0
}

