object Solution {
  def ladderLength(beginWord: String, endWord: String, wordList: Array[String]): Int = {
    val words = mutable.HashSet[String]() // words not visited yet
    words ++= wordList
    if (!words.contains(endWord)) return 0
    words -= beginWord
    val queue = mutable.Queue[String](beginWord)
    var steps = 1
    var answer = 0
    while (answer == 0 && queue.nonEmpty) {
      var left = queue.size // one BFS level = one more word in the ladder
      while (left > 0 && answer == 0) {
        val word = queue.dequeue()
        left -= 1
        if (word == endWord) {
          answer = steps
        } else {
          for (i <- 0 until word.length; ch <- 'a' to 'z') {
            val candidate = word.substring(0, i) + ch + word.substring(i + 1)
            if (words.remove(candidate)) { // removing = mark visited
              queue.enqueue(candidate)
            }
          }
        }
      }
      steps += 1
    }
    answer
  }
}

