import "container/heap"

// courseHeap is a min-heap of course numbers.
type courseHeap []int

func (h courseHeap) Len() int           { return len(h) }
func (h courseHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h courseHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *courseHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *courseHeap) Pop() any {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}

func findOrder(numCourses int, prerequisites [][]int) []int {
	adj := make([][]int, numCourses) // adj[b] = courses that need b
	indegree := make([]int, numCourses)
	for _, p := range prerequisites {
		adj[p[1]] = append(adj[p[1]], p[0])
		indegree[p[0]]++
	}
	// min-heap: among the courses we can take now, always pick the smallest number
	ready := &courseHeap{}
	for i := 0; i < numCourses; i++ {
		if indegree[i] == 0 {
			heap.Push(ready, i)
		}
	}
	order := []int{}
	for ready.Len() > 0 {
		u := heap.Pop(ready).(int)
		order = append(order, u)
		for _, v := range adj[u] {
			indegree[v]--
			if indegree[v] == 0 {
				heap.Push(ready, v)
			}
		}
	}
	if len(order) != numCourses { // shorter means a cycle
		return nil
	}
	return order
}

