import heapq


def alien_order(words: list[str]) -> str:
    adj = {c: set() for w in words for c in w}  # letter -> letters that must come after it
    indeg = {c: 0 for c in adj}
    for a, b in zip(words, words[1:]):
        if len(a) > len(b) and a.startswith(b):
            return ""  # a longer word cannot come before its own prefix
        for x, y in zip(a, b):
            if x != y:  # the first different letters give one rule: x before y
                if y not in adj[x]:
                    adj[x].add(y)
                    indeg[y] += 1
                break
    heap = [c for c in adj if indeg[c] == 0]
    heapq.heapify(heap)  # always take the smallest available letter
    out = []
    while heap:
        u = heapq.heappop(heap)
        out.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    return "".join(out) if len(out) == len(adj) else ""  # fewer letters means a cycle

