import "container/heap"

type letterHeap []int

func (h letterHeap) Len() int           { return len(h) }
func (h letterHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h letterHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *letterHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *letterHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func alienOrder(words []string) string {
	var present [26]bool
	var adj [26][26]bool // adj[x][y]: x must come before y
	var indeg [26]int
	total := 0
	for _, w := range words {
		for i := 0; i < len(w); i++ {
			if c := int(w[i] - 'a'); !present[c] {
				present[c] = true
				total++
			}
		}
	}
	for i := 0; i+1 < len(words); i++ {
		a, b := words[i], words[i+1]
		j := 0
		for j < len(a) && j < len(b) && a[j] == b[j] {
			j++
		}
		if j == len(a) || j == len(b) {
			if len(a) > len(b) {
				return "" // a longer word cannot come before its own prefix
			}
			continue
		}
		x, y := int(a[j]-'a'), int(b[j]-'a')
		if !adj[x][y] {
			adj[x][y] = true
			indeg[y]++
		}
	}
	h := &letterHeap{} // always take the smallest available letter
	for c := 0; c < 26; c++ {
		if present[c] && indeg[c] == 0 {
			heap.Push(h, c)
		}
	}
	out := []byte{}
	for h.Len() > 0 {
		u := heap.Pop(h).(int)
		out = append(out, byte('a'+u))
		for v := 0; v < 26; v++ {
			if adj[u][v] {
				indeg[v]--
				if indeg[v] == 0 {
					heap.Push(h, v)
				}
			}
		}
	}
	if len(out) != total {
		return "" // a cycle
	}
	return string(out)
}

