import "container/heap"

type delayHeap [][2]int // {distance, node}, smallest distance first

func (h delayHeap) Len() int           { return len(h) }
func (h delayHeap) Less(i, j int) bool { return h[i][0] < h[j][0] }
func (h delayHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *delayHeap) Push(x any)        { *h = append(*h, x.([2]int)) }
func (h *delayHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func networkDelayTime(times [][]int, n int, k int) int {
	const inf = 1 << 60
	adj := make([][][2]int, n+1) // adj[u] = list of {v, w}
	for _, t := range times {
		adj[t[0]] = append(adj[t[0]], [2]int{t[1], t[2]})
	}
	dist := make([]int, n+1)
	for i := range dist {
		dist[i] = inf
	}
	dist[k] = 0
	h := &delayHeap{{0, k}}
	for h.Len() > 0 {
		cur := heap.Pop(h).([2]int)
		d, u := cur[0], cur[1]
		if d > dist[u] {
			continue // stale entry: u was already reached faster
		}
		for _, e := range adj[u] {
			if d+e[1] < dist[e[0]] {
				dist[e[0]] = d + e[1]
				heap.Push(h, [2]int{dist[e[0]], e[0]})
			}
		}
	}
	slowest := 0
	for i := 1; i <= n; i++ {
		if dist[i] > slowest {
			slowest = dist[i]
		}
	}
	if slowest == inf {
		return -1
	}
	return slowest
}

