		if d > dist[r][c] {
			continue // stale entry
		}
		if r == rows-1 && c == cols-1 {
			return d
		}
		for _, dir := range dirs {
			nr, nc := r+dir[0], c+dir[1]
			if nr < 0 || nc < 0 || nr >= rows || nc >= cols {
				continue
			}
			// effort of a path is its largest step, not the sum of steps
			step := heights[nr][nc] - heights[r][c]
			if step < 0 {
				step = -step
			}
			nd := max(d, step)
			if nd < dist[nr][nc] {
				dist[nr][nc] = nd
				heap.Push(h, [3]int{nd, nr, nc})
			}
		}
	}
	return 0
}

