from bisect import bisect_left


def length_of_lis(nums: list[int]) -> int:
    tails = []  # tails[k] = smallest last value of an increasing subsequence of length k + 1
    for x in nums:
        i = bisect_left(tails, x)  # first tail >= x (strictly increasing, so equal values replace)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

