object Solution {
  def lengthOfLis(nums: Array[Int]): Int = {
    val tails = new Array[Int](nums.length) // tails(k) = smallest last value of an increasing subsequence of length k + 1
    var size = 0
    for (x <- nums) {
      // binary search for the first tail >= x
      var lo = 0
      var hi = size
      while (lo < hi) {
        val mid = (lo + hi) / 2
        if (tails(mid) < x) lo = mid + 1 else hi = mid
      }
      tails(lo) = x
      if (lo == size) size += 1
    }
    size
  }
}

