def can_partition(nums: list[int]) -> bool:
    total = sum(nums)
    if total % 2 == 1:
        return False
    target = total // 2
    can = [False] * (target + 1)  # can[s] = some subset of the numbers seen so far sums to s
    can[0] = True
    for x in nums:
        for s in range(target, x - 1, -1):  # go downwards so each number is used once
            if can[s - x]:
                can[s] = True
    return can[target]

