def maximal_square(matrix: list[str]) -> int:
    rows = len(matrix)
    cols = len(matrix[0]) if rows else 0
    # dp[r][c] = side of the largest all-1 square whose bottom-right corner is cell (r-1, c-1)
    dp = [[0] * (cols + 1) for _ in range(rows + 1)]
