class Trie:
    def __init__(self):
        self.root = {}  # a node maps a letter to its child node; the key "$" marks the end of a word

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True

    def _find(self, text: str):
        """The node reached by walking text from the root, or None if the path breaks."""
        node = self.root
        for ch in text:
            if ch not in node:
                return None
            node = node[ch]
        return node

    def search(self, word: str) -> bool:
        node = self._find(word)
        return node is not None and "$" in node

    def starts_with(self, prefix: str) -> bool:
        return self._find(prefix) is not None

