class Trie {
    // Nodes live in vectors; node 0 is the root, and 0 in next[] means "no child".
    vector<array<int, 26>> next;
    vector<bool> end;  // a word ends at this node

    int newNode() {
        next.push_back({});  // all zeros
        end.push_back(false);
        return (int)next.size() - 1;
    }

    // The node reached by walking text from the root, or -1 if the path breaks.
    int find(const string& text) {
        int node = 0;
        for (char ch : text) {
            node = next[node][ch - 'a'];
            if (node == 0) return -1;
        }
        return node;
    }

public:
    Trie() {
        newNode();
    }

    void insert(string word) {
        int node = 0;
        for (char ch : word) {
            if (next[node][ch - 'a'] == 0) {
                int child = newNode();
                next[node][ch - 'a'] = child;
            }
            node = next[node][ch - 'a'];
        }
        end[node] = true;
    }

    bool search(string word) {
        int node = find(word);
        return node != -1 && end[node];
    }

    bool startsWith(string prefix) {
        return find(prefix) != -1;
    }
};

