class WordDictionary:
    def __init__(self):
        self.root = {}  # a node maps a letter to its child node; the key "$" marks the end of a word

    def add_word(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True

    def search(self, word: str) -> bool:
        def dfs(node, i):
            if i == len(word):
                return "$" in node
            if word[i] == ".":  # a dot matches any letter: try every child
                return any(dfs(child, i + 1) for key, child in node.items() if key != "$")
            return word[i] in node and dfs(node[word[i]], i + 1)

        return dfs(self.root, 0)

