class WordDictionary {
    // Nodes live in vectors; node 0 is the root, and 0 in next[] means "no child".
    vector<array<int, 26>> next;
    vector<bool> end;  // a word ends at this node

    int newNode() {
        next.push_back({});  // all zeros
        end.push_back(false);
        return (int)next.size() - 1;
    }

    bool dfs(int node, const string& word, int i) {
        if (i == (int)word.size()) return end[node];
        if (word[i] == '.') {  // a dot matches any letter: try every child
            for (int child : next[node]) {
                if (child != 0 && dfs(child, word, i + 1)) return true;
            }
            return false;
        }
        int child = next[node][word[i] - 'a'];
        return child != 0 && dfs(child, word, i + 1);
    }

public:
    WordDictionary() {
        newNode();
    }

    void addWord(string word) {
        int node = 0;
        for (char ch : word) {
            if (next[node][ch - 'a'] == 0) {
                int child = newNode();
                next[node][ch - 'a'] = child;
            }
            node = next[node][ch - 'a'];
        }
        end[node] = true;
    }

    bool search(string word) {
        return dfs(0, word, 0);
    }
};

