struct WordDictionary {
    root: WordNode,
}

impl WordDictionary {
    fn new() -> Self {
        WordDictionary { root: WordNode::default() }
    }

    fn add_word(&mut self, word: String) {
        let mut node = &mut self.root;
        for b in word.bytes() {
            let child = node.next[(b - b'a') as usize].get_or_insert_with(|| Box::new(WordNode::default()));
            node = &mut **child;
        }
        node.end = true;
    }

    // Does the rest of the pattern (from position i) match some word below this node?
    fn dfs(node: &WordNode, pattern: &[u8], i: usize) -> bool {
        if i == pattern.len() {
            return node.end;
        }
        if pattern[i] == b'.' {
            // a dot matches any letter: try every child
            return node.next.iter().flatten().any(|child| Self::dfs(child, pattern, i + 1));
        }
        match &node.next[(pattern[i] - b'a') as usize] {
            Some(child) => Self::dfs(child, pattern, i + 1),
            None => false,
        }
    }

    fn search(&self, word: String) -> bool {
        Self::dfs(&self.root, word.as_bytes(), 0)
    }
}

