def find_words(board: list[str], words: list[str]) -> list[str]:
    # Trie of all words: a node maps a letter to its child; the key "$" holds the word that ends here.
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = w

    grid = [list(row) for row in board]
    rows, cols = len(grid), len(grid[0])
    found = []

    def dfs(r, c, node):
        ch = grid[r][c]
        nxt = node.get(ch)
        if nxt is None:  # no word continues with this letter: prune
            return
        if "$" in nxt:
            found.append(nxt.pop("$"))  # remove the mark so the word is reported once
        grid[r][c] = "#"  # mark the cell as used
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != "#":
                dfs(nr, nc, nxt)
        grid[r][c] = ch  # backtrack

    for r in range(rows):
        for c in range(cols):
            dfs(r, c, root)
    return found

