class Solution {
public:
    vector<string> findWords(vector<string>& board, vector<string>& words) {
        // Trie in a vector: node 0 is the root, and 0 in next[] means "no child".
        struct Node {
            int next[26] = {};
            string word;  // the word that ends here ("" if none)
        };
        vector<Node> trie(1);
        for (const string& w : words) {
            int node = 0;
            for (char ch : w) {
                if (trie[node].next[ch - 'a'] == 0) {
                    trie.emplace_back();
                    trie[node].next[ch - 'a'] = (int)trie.size() - 1;
                }
                node = trie[node].next[ch - 'a'];
            }
            trie[node].word = w;
        }

        int rows = board.size(), cols = board[0].size();
        vector<string> found;
        const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};

        function<void(int, int, int)> dfs = [&](int r, int c, int node) {
            char ch = board[r][c];
            int next = trie[node].next[ch - 'a'];
            if (next == 0) return;  // no word continues with this letter: prune
            if (!trie[next].word.empty()) {
                found.push_back(trie[next].word);
                trie[next].word.clear();  // remove the mark so the word is reported once
            }
            board[r][c] = '#';  // mark the cell as used
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] != '#') dfs(nr, nc, next);
            }
            board[r][c] = ch;  // backtrack
        };

        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) dfs(r, c, 0);
        return found;
    }
};

