struct WsNode {
    next: [Option<Box<WsNode>>; 26],
    word: Option<String>, // the word that ends here
}

impl Solution {
    pub fn find_words(board: Vec<String>, words: Vec<String>) -> Vec<String> {
        let mut root = WsNode::default();
        for w in &words {
            let mut node = &mut root;
            for b in w.bytes() {
                let child = node.next[(b - b'a') as usize].get_or_insert_with(|| Box::new(WsNode::default()));
                node = &mut **child;
            }
            node.word = Some(w.clone());
        }

        let mut grid: Vec<Vec<u8>> = board.iter().map(|row| row.bytes().collect()).collect();
        let mut found = Vec::new();
        for r in 0..grid.len() {
            for c in 0..grid[0].len() {
                Self::dfs(&mut grid, r, c, &mut root, &mut found);
            }
        }
        found
    }

    fn dfs(grid: &mut Vec<Vec<u8>>, r: usize, c: usize, node: &mut WsNode, found: &mut Vec<String>) {
        let ch = grid[r][c];
        let next = match node.next[(ch - b'a') as usize].as_mut() {
            Some(n) => n,
            None => return, // no word continues with this letter: prune
        };
        if let Some(w) = next.word.take() {
            found.push(w); // take() removes the mark so the word is reported once
        }
        grid[r][c] = b'#'; // mark the cell as used
        let (rows, cols) = (grid.len() as i32, grid[0].len() as i32);
        for (dr, dc) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let (nr, nc) = (r as i32 + dr, c as i32 + dc);
            if nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr as usize][nc as usize] != b'#' {
                Self::dfs(grid, nr as usize, nc as usize, next, found);
            }
        }
        grid[r][c] = ch; // backtrack
    }
}

