use std::collections::HashMap;

// A doubly linked list kept in vectors: slot 0 is a sentinel, next[0] is the most recent slot and prev[0] the least recent.
struct LRUCache {
    cap: usize,
    map: HashMap<i32, usize>, // key -> slot
    keys: Vec<i32>,
    vals: Vec<i32>,
    prev: Vec<usize>,
    next: Vec<usize>,
}

impl LRUCache {
    fn new(capacity: i32) -> Self {
        LRUCache { cap: capacity as usize, map: HashMap::new(), keys: vec![0], vals: vec![0], prev: vec![0], next: vec![0] }
    }

    fn unlink(&mut self, i: usize) {
        let (p, n) = (self.prev[i], self.next[i]);
        self.next[p] = n;
        self.prev[n] = p;
    }

    fn push_front(&mut self, i: usize) {
        let first = self.next[0];
        self.prev[i] = 0;
        self.next[i] = first;
        self.prev[first] = i;
        self.next[0] = i;
    }

    fn get(&mut self, key: i32) -> i32 {
        match self.map.get(&key).copied() {
            None => -1,
            Some(i) => {
                self.unlink(i);
                self.push_front(i);
                self.vals[i]
            }
        }
    }

    fn put(&mut self, key: i32, value: i32) {
        if let Some(&i) = self.map.get(&key) {
            self.vals[i] = value;
            self.unlink(i);
            self.push_front(i);
            return;
        }
        let i = if self.map.len() == self.cap {
            let last = self.prev[0]; // reuse the least recently used slot
            self.unlink(last);
            self.map.remove(&self.keys[last]);
            last
        } else {
            self.keys.push(0);
            self.vals.push(0);
            self.prev.push(0);
            self.next.push(0);
            self.keys.len() - 1
        };
        self.keys[i] = key;
        self.vals[i] = value;
        self.map.insert(key, i);
        self.push_front(i);
    }
}

