func spiralOrder(matrix [][]int) []int {
	res := []int{}
	// the unvisited rectangle: rows top..bottom-1 and columns left..right-1
	top, bottom := 0, len(matrix)
	left, right := 0, len(matrix[0])
	for top < bottom && left < right {
		for c := left; c < right; c++ { // top row, left to right
			res = append(res, matrix[top][c])
		}
		top++
		for r := top; r < bottom; r++ { // right column, top to bottom
			res = append(res, matrix[r][right-1])
		}
		right--
		if top < bottom { // a bottom row is still left
			for c := right - 1; c >= left; c-- {
				res = append(res, matrix[bottom-1][c])
			}
			bottom--
		}
		if left < right { // a left column is still left
			for r := bottom - 1; r >= top; r-- {
				res = append(res, matrix[r][left])
			}
			left++
		}
	}
	return res
}

