import scala.collection.mutable.ArrayBuffer

object Solution {
  def spiralOrder(matrix: Array[Array[Int]]): Array[Int] = {
    val res = ArrayBuffer[Int]()
    // the unvisited rectangle: rows top until bottom, columns left until right
    var top = 0
    var bottom = matrix.length
    var left = 0
    var right = matrix(0).length
    while (top < bottom && left < right) {
      for (c <- left until right) { // top row, left to right
        res += matrix(top)(c)
      }
      top += 1
      for (r <- top until bottom) { // right column, top to bottom
        res += matrix(r)(right - 1)
      }
      right -= 1
      if (top < bottom) { // a bottom row is still left
        for (c <- right - 1 to left by -1) {
          res += matrix(bottom - 1)(c)
        }
        bottom -= 1
      }
      if (left < right) { // a left column is still left
        for (r <- bottom - 1 to top by -1) {
          res += matrix(r)(left)
        }
        left += 1
      }
    }
    res.toArray
  }
}

