      for (d <- 0 until 4) {
        val nr = r + dr(d)
        val nc = c + dc(d)
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && dist(nr)(nc) == -1) {
          dist(nr)(nc) = dist(r)(c) + 1
          queue.enqueue((nr, nc))
        }
      }
    }
