function splitArray(nums, k) {
  let lo = Math.max(...nums), hi = nums.reduce((a, b) => a + b, 0);
  const pieces = limit => {
    let count = 1, sum = 0;
    for (const x of nums) {
      if (sum + x > limit) { count++; sum = 0; }
      sum += x;
    }
    return count;
  };
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (pieces(mid) <= k) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

