def split_array(nums: list[int], k: int) -> int:
    def pieces(limit: int) -> int:
        # greedy: how many pieces are needed if no piece may exceed `limit`
        count, total = 1, 0
        for x in nums:
            if total + x > limit:
                count += 1
                total = 0
            total += x
        return count

    # the answer is at least the biggest number and at most the sum of everything
    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if pieces(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

