def kth_smallest(matrix: list[list[int]], k: int) -> int:
    n = len(matrix)

    def count_at_most(x: int) -> int:
        # walk from the bottom-left corner: right when the cell fits, up when it does not
        count, r, c = 0, n - 1, 0
        while r >= 0 and c < n:
            if matrix[r][c] <= x:
                count += r + 1  # the whole column above is <= x too
                c += 1
            else:
                r -= 1
        return count

    # binary search on the value, between the smallest and the largest cell
    lo, hi = matrix[0][0], matrix[n - 1][n - 1]
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

