class Solution {
public:
    int kthSmallest(vector<vector<int>>& matrix, int k) {
        int n = matrix.size();
        auto countAtMost = [&](int x) {
            // walk from the bottom-left corner: right when the cell fits, up when it does not
            int count = 0, r = n - 1, c = 0;
            while (r >= 0 && c < n) {
                if (matrix[r][c] <= x) {
                    count += r + 1;  // the whole column above is <= x too
                    c++;
                } else {
                    r--;
                }
            }
            return count;
        };
        // binary search on the value, between the smallest and the largest cell
        long long lo = matrix[0][0], hi = matrix[n - 1][n - 1];
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            if (countAtMost((int)mid) >= k) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }
};

