class Solution {
public:
    vector<vector<int>> cloneGraph(vector<vector<int>>& adjList) {
        if (adjList.empty()) return {};
        // build the original graph: node i + 1 has neighbours adjList[i]
        vector<GraphNode*> nodes;
        for (int i = 0; i < (int)adjList.size(); i++) nodes.push_back(new GraphNode(i + 1));
        for (int i = 0; i < (int)adjList.size(); i++)
            for (int v : adjList[i]) nodes[i]->neighbors.push_back(nodes[v - 1]);

        unordered_map<GraphNode*, GraphNode*> copies;  // original node -> its copy
        copyNode(nodes[0], copies);

        // read the copy back as an adjacency list
        vector<vector<int>> out(adjList.size());
        for (auto& [orig, c] : copies)
            for (GraphNode* nb : c->neighbors) out[c->val - 1].push_back(nb->val);
        return out;
    }

private:
    GraphNode* copyNode(GraphNode* node, unordered_map<GraphNode*, GraphNode*>& copies) {
        auto it = copies.find(node);
        if (it != copies.end()) return it->second;
        GraphNode* c = new GraphNode(node->val);
        copies[node] = c;  // register before visiting the neighbours: this breaks cycles
        for (GraphNode* nb : node->neighbors) c->neighbors.push_back(copyNode(nb, copies));
        return c;
    }
};

