use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

struct GraphNode {
    val: i32,
    neighbors: Vec<Rc<RefCell<GraphNode>>>,
}

impl Solution {
    pub fn clone_graph(adj_list: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
        if adj_list.is_empty() {
            return vec![];
        }
        // build the original graph: node i + 1 has neighbours adj_list[i]
        let nodes: Vec<Rc<RefCell<GraphNode>>> = (0..adj_list.len())
            .map(|i| Rc::new(RefCell::new(GraphNode { val: i as i32 + 1, neighbors: vec![] })))
            .collect();
        for (i, nbrs) in adj_list.iter().enumerate() {
            for &v in nbrs {
                nodes[i].borrow_mut().neighbors.push(Rc::clone(&nodes[v as usize - 1]));
            }
        }

        // original node (identified by its address) -> its copy
        let mut copies: HashMap<usize, Rc<RefCell<GraphNode>>> = HashMap::new();
        Self::copy_node(&nodes[0], &mut copies);

        // read the copy back as an adjacency list
        let mut out: Vec<Vec<i32>> = vec![vec![]; adj_list.len()];
        for c in copies.values() {
            let c = c.borrow();
            out[c.val as usize - 1] = c.neighbors.iter().map(|nb| nb.borrow().val).collect();
        }
        out
    }

    fn copy_node(
        node: &Rc<RefCell<GraphNode>>,
        copies: &mut HashMap<usize, Rc<RefCell<GraphNode>>>,
    ) -> Rc<RefCell<GraphNode>> {
        let key = Rc::as_ptr(node) as usize;
        if let Some(c) = copies.get(&key) {
            return Rc::clone(c);
        }
        let copy = Rc::new(RefCell::new(GraphNode { val: node.borrow().val, neighbors: vec![] }));
        copies.insert(key, Rc::clone(&copy)); // register before visiting the neighbours: this breaks cycles
        let nbrs: Vec<Rc<RefCell<GraphNode>>> = node.borrow().neighbors.clone();
        for nb in &nbrs {
            let c = Self::copy_node(nb, copies);
            copy.borrow_mut().neighbors.push(c);
        }
        copy
    }
}

