object Solution {
  def cloneGraph(adjList: Array[Array[Int]]): Array[Array[Int]] = {
    if (adjList.isEmpty) return Array.empty[Array[Int]]
    // build the original graph: node i + 1 has neighbours adjList[i]
    val nodes = Array.tabulate(adjList.length)(i => new GraphNode(i + 1))
    for (i <- adjList.indices; v <- adjList(i)) nodes(i).neighbors += nodes(v - 1)

    val copies = mutable.HashMap[GraphNode, GraphNode]() // original node -> its copy
    def copyNode(node: GraphNode): GraphNode = {
      if (copies.contains(node)) copies(node)
      else {
        val c = new GraphNode(node.value)
        copies(node) = c // register before visiting the neighbours: this breaks cycles
        for (nb <- node.neighbors) c.neighbors += copyNode(nb)
        c
      }
    }
    copyNode(nodes(0))

    // read the copy back as an adjacency list
    val out = new Array[Array[Int]](adjList.length)
    for ((_, c) <- copies) out(c.value - 1) = c.neighbors.map(_.value).toArray
    out
  }
}

