def decode_string(s: str) -> str:
    counts = []    # repeat count of each open "["
    prefixes = []  # text built before each open "["
    cur = ""
    num = 0
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == "[":
            counts.append(num)
            prefixes.append(cur)
            num = 0
            cur = ""
        elif ch == "]":
            cur = prefixes.pop() + cur * counts.pop()
        else:
            cur += ch
    return cur

