import "sort"

func jobScheduling(startTime []int, endTime []int, profit []int) int {
	n := len(startTime)
	order := make([]int, n) // job indexes sorted by end time
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool { return endTime[order[a]] < endTime[order[b]] })

	ends := make([]int, 0, n) // end times of the jobs seen so far, in sorted order
	best := make([]int, 1, n+1) // best[i] = max profit using only the first i jobs
	for _, k := range order {
		// how many earlier jobs end at or before this job starts
		j := sort.Search(len(ends), func(i int) bool { return ends[i] > startTime[k] })
		best = append(best, max(best[len(best)-1], best[j]+profit[k])) // skip the job, or take it
		ends = append(ends, endTime[k])
	}
	return best[len(best)-1]
}

