class Solution {
public:
    int jobScheduling(vector<int>& startTime, vector<int>& endTime, vector<int>& profit) {
        int n = startTime.size();
        vector<int> order(n);  // job indexes sorted by end time
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return endTime[a] < endTime[b]; });

        vector<int> ends;     // end times of the jobs seen so far, in sorted order
        vector<int> best{0};  // best[i] = max profit using only the first i jobs
        for (int k : order) {
            // how many earlier jobs end at or before this job starts
            int j = upper_bound(ends.begin(), ends.end(), startTime[k]) - ends.begin();
            best.push_back(max(best.back(), best[j] + profit[k]));  // skip the job, or take it
            ends.push_back(endTime[k]);
        }
        return best.back();
    }
};

