object Solution {
  def jobScheduling(startTime: Array[Int], endTime: Array[Int], profit: Array[Int]): Int = {
    val n = startTime.length
    val order = (0 until n).sortBy(k => endTime(k)) // job indexes sorted by end time

    val ends = new Array[Int](n)     // end times of the jobs seen so far, in sorted order
    val best = new Array[Int](n + 1) // best(i) = max profit using only the first i jobs
    var count = 0
    for (k <- order) {
      // binary search: how many earlier jobs end at or before this job starts
      var lo = 0
      var hi = count
      while (lo < hi) {
        val mid = (lo + hi) / 2
        if (ends(mid) <= startTime(k)) lo = mid + 1 else hi = mid
      }
      best(count + 1) = math.max(best(count), best(lo) + profit(k)) // skip the job, or take it
      ends(count) = endTime(k)
      count += 1
    }
    best(count)
  }
}

