import heapq

def k_closest(points: list[list[int]], k: int) -> list[list[int]]:
    # max-heap (negated distance) of the k closest points so far: (-dist, index)
    heap = []
    for i, (x, y) in enumerate(points):
        dist = x * x + y * y  # no square root needed to compare distances
        if len(heap) < k:
            heapq.heappush(heap, (-dist, i))
        elif dist < -heap[0][0]:
            heapq.heapreplace(heap, (-dist, i))  # farthest of the k leaves
    return [points[i] for _, i in heap]

