import "container/heap"

type closestEntry struct{ dist, idx int }

// closestMaxHeap is a max-heap ordered by dist: the farthest kept point is on top.
type closestMaxHeap []closestEntry

func (h closestMaxHeap) Len() int           { return len(h) }
func (h closestMaxHeap) Less(i, j int) bool { return h[i].dist > h[j].dist }
func (h closestMaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *closestMaxHeap) Push(x any)        { *h = append(*h, x.(closestEntry)) }
func (h *closestMaxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func kClosest(points [][]int, k int) [][]int {
	h := &closestMaxHeap{} // the k closest points so far
	for i, p := range points {
		dist := p[0]*p[0] + p[1]*p[1] // no square root needed to compare distances
		if h.Len() < k {
			heap.Push(h, closestEntry{dist, i})
		} else if dist < (*h)[0].dist {
			(*h)[0] = closestEntry{dist, i} // replace the farthest, then restore the heap
			heap.Fix(h, 0)
		}
	}
	res := make([][]int, 0, k)
	for _, e := range *h {
		res = append(res, points[e.idx])
	}
	return res
}

