class Solution {
public:
    vector<vector<int>> kClosest(vector<vector<int>>& points, int k) {
        // max-heap of {distance, index}: the farthest of the k closest points is on top
        priority_queue<pair<int, int>> heap;
        for (int i = 0; i < (int)points.size(); i++) {
            int dist = points[i][0] * points[i][0] + points[i][1] * points[i][1];  // no sqrt needed
            if ((int)heap.size() < k) {
                heap.push({dist, i});
            } else if (dist < heap.top().first) {
                heap.pop();  // drop the farthest
                heap.push({dist, i});
            }
        }
        vector<vector<int>> res;
        while (!heap.empty()) {
            res.push_back(points[heap.top().second]);
            heap.pop();
        }
        return res;
    }
};

