from collections import Counter

def least_interval(tasks: list[str], n: int) -> int:
    freq = Counter(tasks)
    max_freq = max(freq.values())
    count_max = sum(1 for f in freq.values() if f == max_freq)
    # (max_freq - 1) full frames of size n + 1, plus the last row of the most frequent tasks;
    # if there are enough other tasks to fill every gap, no idle time is needed
    return max(len(tasks), (max_freq - 1) * (n + 1) + count_max)

