fn palin_dfs(start: usize, s: &str, cur: &mut Vec<String>, res: &mut Vec<Vec<String>>) {
    if start == s.len() {
        res.push(cur.clone());
        return;
    }
    for end in start..s.len() {
        if is_palindrome(s.as_bytes(), start, end) {
            cur.push(s[start..=end].to_string());
            palin_dfs(end + 1, s, cur, res);
            cur.pop();
        }
    }
}

