import scala.collection.mutable.ArrayBuffer

object Solution {
  def partition(s: String): Array[Array[String]] = {
    val res = ArrayBuffer[Array[String]]()
    val cur = ArrayBuffer[String]()
    def isPal(l0: Int, r0: Int): Boolean = {
      var l = l0
      var r = r0
      while (l < r && s.charAt(l) == s.charAt(r)) {
        l += 1
        r -= 1
      }
      l >= r
    }
    def dfs(start: Int): Unit = {
      if (start == s.length) {
        res += cur.toArray
      } else {
        for (end <- start until s.length) {
          if (isPal(start, end)) {
            cur += s.substring(start, end + 1)
            dfs(end + 1)
            cur.remove(cur.length - 1)
          }
        }
      }
    }
    dfs(0)
    res.toArray
  }
}

