func maximumSubarraySum(nums []int, k int) int {
	count := map[int]int{} // value -> how many times it is in the window
	total, best := 0, 0
	for i, x := range nums {
		total += x
		count[x]++
		if i >= k { // the window is too long: drop the element that left
			out := nums[i-k]
			total -= out
			count[out]--
			if count[out] == 0 {
				delete(count, out)
			}
		}
		// k distinct values in a window of k elements means all are different
		if i >= k-1 && len(count) == k && total > best {
			best = total
		}
	}
	return best
}

