        for i in 0..nums.len() {
            total += nums[i] as i64;
            *count.entry(nums[i]).or_insert(0) += 1;
            if i >= k {
                // the window is too long: drop the element that left
                let out = nums[i - k];
                total -= out as i64;
                let c = count.get_mut(&out).unwrap();
                *c -= 1;
                if *c == 0 {
                    count.remove(&out);
                }
            }
            // k distinct values in a window of k elements means all are different
            if i + 1 >= k && count.len() == k {
                best = best.max(total);
            }
        }
