object Solution {
  def maximumSubarraySum(nums: Array[Int], k: Int): Long = {
    val count = mutable.HashMap[Int, Int]() // value -> how many times it is in the window
    var total = 0L
    var best = 0L
    for (i <- nums.indices) {
      total += nums(i)
      count(nums(i)) = count.getOrElse(nums(i), 0) + 1
      if (i >= k) { // the window is too long: drop the element that left
        val out = nums(i - k)
        total -= out
        val c = count(out) - 1
        if (c == 0) count.remove(out) else count(out) = c
      }
      // k distinct values in a window of k elements means all are different
      if (i >= k - 1 && count.size == k) best = math.max(best, total)
    }
    best
  }
}

