impl Solution {
    pub fn find_the_city(n: i32, edges: Vec<Vec<i32>>, distance_threshold: i32) -> i32 {
        let n = n as usize;
        const INF: i32 = 1_000_000_000; // INF + INF still fits in an i32
        // Floyd-Warshall: dist[i][j] = shortest path length from i to j
        let mut dist = vec![vec![INF; n]; n];
        for i in 0..n {
            dist[i][i] = 0;
        }
        for e in &edges {
            let (a, b, w) = (e[0] as usize, e[1] as usize, e[2]);
            dist[a][b] = dist[a][b].min(w);
            dist[b][a] = dist[b][a].min(w);
        }
        for k in 0..n {
            for i in 0..n {
                for j in 0..n {
                    let via = dist[i][k] + dist[k][j];
                    if via < dist[i][j] {
                        dist[i][j] = via;
                    }
                }
            }
        }
        let (mut answer, mut fewest) = (-1, n + 1);
        for i in 0..n {
            let reachable = (0..n).filter(|&j| i != j && dist[i][j] <= distance_threshold).count();
            if reachable <= fewest {
                // <= keeps the larger index on ties
                fewest = reachable;
                answer = i as i32;
            }
        }
        answer
    }
}

