def calc_equation(equations: list[list[str]], values: list[float], queries: list[list[str]]) -> list[float]:
    ids = {}  # variable name -> row/column number
    for a, b in equations:
        ids.setdefault(a, len(ids))
        ids.setdefault(b, len(ids))
    n = len(ids)
    # ratio[i][j] = i / j, or -1 when not known yet
    ratio = [[1.0 if i == j else -1.0 for j in range(n)] for i in range(n)]
    for (a, b), v in zip(equations, values):
        ratio[ids[a]][ids[b]] = v
        ratio[ids[b]][ids[a]] = 1 / v
    # Floyd-Warshall: i / j = (i / k) * (k / j)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if ratio[i][j] == -1 and ratio[i][k] != -1 and ratio[k][j] != -1:
                    ratio[i][j] = ratio[i][k] * ratio[k][j]
    return [ratio[ids[a]][ids[b]] if a in ids and b in ids else -1.0 for a, b in queries]

