	ids := map[string]int{} // variable name -> row/column number
	for _, e := range equations {
		for _, name := range e {
			if _, ok := ids[name]; !ok {
				ids[name] = len(ids)
			}
		}
	}
	n := len(ids)
	// ratio[i][j] = i / j, or -1 when not known yet
	ratio := make([][]float64, n)
	for i := range ratio {
		ratio[i] = make([]float64, n)
		for j := range ratio[i] {
			ratio[i][j] = -1
		}
		ratio[i][i] = 1
	}
	for idx, e := range equations {
		a, b := ids[e[0]], ids[e[1]]
		ratio[a][b] = values[idx]
		ratio[b][a] = 1 / values[idx]
	}
	// Floyd-Warshall: i / j = (i / k) * (k / j)
	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				if ratio[i][j] == -1 && ratio[i][k] != -1 && ratio[k][j] != -1 {
					ratio[i][j] = ratio[i][k] * ratio[k][j]
				}
			}
