public:
    vector<double> calcEquation(vector<vector<string>>& equations, vector<double>& values, vector<vector<string>>& queries) {
        unordered_map<string, int> ids;  // variable name -> row/column number
        for (auto& e : equations)
            for (auto& name : e)
                if (!ids.count(name)) {
                    int next = ids.size();
                    ids[name] = next;
                }
        int n = ids.size();
        // ratio[i][j] = i / j, or -1 when not known yet
        vector<vector<double>> ratio(n, vector<double>(n, -1.0));
        for (int i = 0; i < n; i++) ratio[i][i] = 1.0;
        for (size_t idx = 0; idx < equations.size(); idx++) {
            int a = ids[equations[idx][0]], b = ids[equations[idx][1]];
            ratio[a][b] = values[idx];
            ratio[b][a] = 1.0 / values[idx];
        }
        // Floyd-Warshall: i / j = (i / k) * (k / j)
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    if (ratio[i][j] == -1 && ratio[i][k] != -1 && ratio[k][j] != -1)
                        ratio[i][j] = ratio[i][k] * ratio[k][j];
        vector<double> out;
        for (auto& q : queries) {
            auto a = ids.find(q[0]), b = ids.find(q[1]);
            if (a != ids.end() && b != ids.end()) out.push_back(ratio[a->second][b->second]);
            else out.push_back(-1.0);
        }
        return out;
    }
};

