import "sort"

func findMinArrowShots(points [][]int) int {
	if len(points) == 0 {
		return 0
	}
	sort.Slice(points, func(a, b int) bool { return points[a][1] < points[b][1] }) // by right end
	arrows := 1
	pos := points[0][1] // shoot at the right end of the first balloon
	for _, p := range points[1:] {
		if p[0] > pos { // not burst yet: new arrow at this right end
			arrows++
			pos = p[1]
		}
	}
	return arrows
}

