func reorderList(head *ListNode) *ListNode {
	if head == nil || head.Next == nil {
		return head
	}
	// 1. find the middle: slow ends at the last node of the first half
	slow, fast := head, head
	for fast.Next != nil && fast.Next.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
	}
	// 2. cut the list there and reverse the second half
	var prev *ListNode
	cur := slow.Next
	slow.Next = nil
	for cur != nil {
		next := cur.Next
		cur.Next = prev
		prev, cur = cur, next
	}
	// 3. weave: one node from the first half, then one from the reversed second half
	a, b := head, prev
	for b != nil {
		aNext, bNext := a.Next, b.Next
		a.Next = b
		b.Next = aNext
		a, b = aNext, bNext
	}
	return head
}

