impl Solution {
    pub fn reorder_list(head: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
        let mut head = head;
        // 1. count the nodes; the first half keeps (len + 1) / 2 of them
        let mut len = 0;
        let mut cur = &head;
        while let Some(node) = cur {
            len += 1;
            cur = &node.next;
        }
        // 2. cut the list after the first half and reverse the second half
        let mut cut = &mut head;
        for _ in 0..(len + 1) / 2 {
            cut = &mut cut.as_mut().unwrap().next;
        }
        let mut rest = cut.take();
        let mut reversed = None;
        while let Some(mut node) = rest {
            rest = node.next.take();
            node.next = reversed;
            reversed = Some(node);
        }
        // 3. weave: one node from the first half, then one from the reversed second half
        let mut dummy = Box::new(ListNode::new(0));
        let mut tail = &mut dummy;
        let mut a = head;
        let mut b = reversed;
        while a.is_some() || b.is_some() {
            if let Some(mut node) = a.take() {
                a = node.next.take();
                tail.next = Some(node);
                tail = tail.next.as_mut().unwrap();
            }
            if let Some(mut node) = b.take() {
                b = node.next.take();
                tail.next = Some(node);
                tail = tail.next.as_mut().unwrap();
            }
        }
        dummy.next
    }
}

