import (
	"sort"
	"strconv"
	"strings"
)

func largestNumber(nums []int) string {
	strs := make([]string, len(nums))
	for i, x := range nums {
		strs[i] = strconv.Itoa(x)
	}
	// a goes before b when "ab" is bigger than "ba"
	sort.Slice(strs, func(i, j int) bool { return strs[i]+strs[j] > strs[j]+strs[i] })
	if strs[0] == "0" { // the biggest piece is 0, so every piece is 0
		return "0"
	}
	return strings.Join(strs, "")
}

