  const small = sorted.slice(0, mid).reverse();
  const large = sorted.slice(mid).reverse();
  const out = new Array(n);
  for (let i = 0; i < n; i++) {
    out[i] = i % 2 === 0 ? small[i >> 1] : large[i >> 1];
  }
  return out;
}

