import "sort"

func wiggleSort(nums []int) []int {
	s := append([]int(nil), nums...)
	sort.Ints(s)
	n := len(s)
	mid := (n + 1) / 2 // the smaller half is s[:mid], the larger half is s[mid:]
	out := make([]int, n)
	for i := 0; i < n; i++ {
		// even slots take the smaller half from its largest value down,
		// odd slots take the larger half from its largest value down
		if i%2 == 0 {
			out[i] = s[mid-1-i/2]
		} else {
			out[i] = s[n-1-i/2]
		}
	}
	return out
}

