      dx /= g;
      dy /= g;
      if (dx < 0 || (dx === 0 && dy < 0)) {
        dx = -dx;
        dy = -dy;
      }
      const key = dx + ',' + dy;
      const c = (count.get(key) || 0) + 1;
      count.set(key, c);
      if (c + 1 > best) best = c + 1;
    }
  }
  return best;
}

