func maxPoints(points [][]int) int {
	n := len(points)
	if n <= 2 {
		return n
	}
	best := 1
	for i := 0; i < n; i++ {
		slopes := map[[2]int]int{} // reduced direction (dx, dy) from point i -> how many points lie that way
		for j := i + 1; j < n; j++ {
			dx := points[j][0] - points[i][0]
			dy := points[j][1] - points[i][1]
			g := gcdOfPoints(dx, dy)
			dx, dy = dx/g, dy/g
			if dx < 0 || (dx == 0 && dy < 0) { // one sign convention for both directions
				dx, dy = -dx, -dy
			}
			slopes[[2]int{dx, dy}]++
			if c := slopes[[2]int{dx, dy}] + 1; c > best { // +1 for point i itself
				best = c
			}
		}
	}
	return best
}

func gcdOfPoints(a, b int) int {
	if a < 0 {
		a = -a
	}
	if b < 0 {
		b = -b
	}
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

