def shortest_palindrome(s: str) -> str:
    if not s:
        return s
    rev = s[::-1]
    t = s + "#" + rev  # '#' keeps a match from crossing the middle
    lps = [0] * len(t)  # lps[i] = longest proper prefix of t[:i+1] that is also its suffix
    k = 0
    for i in range(1, len(t)):
        while k > 0 and t[i] != t[k]:
            k = lps[k - 1]
        if t[i] == t[k]:
            k += 1
        lps[i] = k
    # k is now the length of the longest prefix of s that is a palindrome
    return rev[: len(s) - k] + s

