func shortestPalindrome(s string) string {
	n := len(s)
	if n == 0 {
		return s
	}
	r := []byte(s)
	for i, j := 0, n-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	rev := string(r)
	t := s + "#" + rev // '#' keeps a match from crossing the middle
	lps := make([]int, len(t)) // lps[i] = longest proper prefix of t[:i+1] that is also its suffix
	k := 0
	for i := 1; i < len(t); i++ {
		for k > 0 && t[i] != t[k] {
			k = lps[k-1]
		}
		if t[i] == t[k] {
			k++
		}
		lps[i] = k
	}
	// k is now the length of the longest prefix of s that is a palindrome
	return rev[:n-k] + s
}

