function runLFUCache(ops, args) {
  let cap = 0, minFreq = 0;
  const value = new Map();
  const freq = new Map();
  const buckets = new Map();
  const addToBucket = (f, k) => {
    if (!buckets.has(f)) buckets.set(f, new Map());
    buckets.get(f).set(k, true);
  };
  const touch = k => {
    const f = freq.get(k);
    const b = buckets.get(f);
    b.delete(k);
    if (b.size === 0) {
      buckets.delete(f);
      if (minFreq === f) minFreq = f + 1;
    }
    freq.set(k, f + 1);
    addToBucket(f + 1, k);
  };
  return ops.map((op, i) => {
    if (op === 'LFUCache') {
      cap = args[i][0];
      return null;
    }
    if (op === 'get') {
      const k = args[i][0];
      if (!value.has(k)) return -1;
      touch(k);
      return value.get(k);
    }
    const [k, v] = args[i];
    if (cap === 0) return null;
    if (value.has(k)) {
      value.set(k, v);
      touch(k);
      return null;
    }
    if (value.size >= cap) {
      const b = buckets.get(minFreq);
      const victim = b.keys().next().value;
      b.delete(victim);
      if (b.size === 0) buckets.delete(minFreq);
      value.delete(victim);
      freq.delete(victim);
    }
    value.set(k, v);
    freq.set(k, 1);
    addToBucket(1, k);
    minFreq = 1;
    return null;
  });
}

