import "container/list"

type lfuEntry struct{ key, value, freq int }

type LFUCache struct {
	cap     int
	minFreq int
	items   map[int]*list.Element // key -> its element
	buckets map[int]*list.List    // count -> entries with that count, front = oldest use
}

func Constructor(capacity int) LFUCache {
	return LFUCache{cap: capacity, items: map[int]*list.Element{}, buckets: map[int]*list.List{}}
}

// pushBack appends the entry to the bucket of its count and returns its new element.
func (this *LFUCache) pushBack(entry *lfuEntry) *list.Element {
	bucket, ok := this.buckets[entry.freq]
	if !ok {
		bucket = list.New()
		this.buckets[entry.freq] = bucket
	}
	return bucket.PushBack(entry)
}

// touch counts one more use: the entry moves to the end of the bucket of count + 1.
func (this *LFUCache) touch(e *list.Element) {
	entry := e.Value.(*lfuEntry)
	bucket := this.buckets[entry.freq]
	bucket.Remove(e)
	if bucket.Len() == 0 {
		delete(this.buckets, entry.freq)
		if this.minFreq == entry.freq {
			this.minFreq++
		}
	}
	entry.freq++
	this.items[entry.key] = this.pushBack(entry)
}

func (this *LFUCache) Get(key int) int {
	e, ok := this.items[key]
	if !ok {
		return -1
	}
	entry := e.Value.(*lfuEntry)
	this.touch(e)
	return entry.value
}

func (this *LFUCache) Put(key int, value int) {
	if this.cap == 0 {
		return
	}
	if e, ok := this.items[key]; ok {
		e.Value.(*lfuEntry).value = value
		this.touch(e)
		return
	}
	if len(this.items) >= this.cap {
		// evict the oldest entry of the lowest count
		bucket := this.buckets[this.minFreq]
		oldest := bucket.Front()
		bucket.Remove(oldest)
		if bucket.Len() == 0 {
			delete(this.buckets, this.minFreq)
		}
		delete(this.items, oldest.Value.(*lfuEntry).key)
	}
	this.items[key] = this.pushBack(&lfuEntry{key, value, 1})
	this.minFreq = 1
}

