cpp.solution:
class LFUCache {
    struct Entry {
        int key, value, freq;
    };
    int cap, minFreq = 0;
    unordered_map<int, list<Entry>> buckets;          // count -> entries with that count, front = oldest use
    unordered_map<int, list<Entry>::iterator> where;  // key -> its entry

    // one more use: the entry moves to the end of the bucket of count + 1
    void touch(int key) {
        auto it = where[key];
        Entry e = *it;
        int f = e.freq;
        buckets[f].erase(it);
        if (buckets[f].empty()) {
            buckets.erase(f);
            if (minFreq == f) minFreq = f + 1;
        }
        e.freq = f + 1;
        buckets[f + 1].push_back(e);
        where[key] = prev(buckets[f + 1].end());
    }

public:
    LFUCache(int capacity) : cap(capacity) {}

    int get(int key) {
        if (!where.count(key)) return -1;
        touch(key);
        return where[key]->value;
    }

    void put(int key, int value) {
        if (cap == 0) return;
        if (where.count(key)) {
            where[key]->value = value;
            touch(key);
            return;
        }
        if ((int)where.size() >= cap) {
            // evict the oldest entry of the lowest count
            auto& bucket = buckets[minFreq];
            where.erase(bucket.front().key);
            bucket.pop_front();
            if (bucket.empty()) buckets.erase(minFreq);
        }
        buckets[1].push_back({key, value, 1});
        where[key] = prev(buckets[1].end());
        minFreq = 1;
    }
};

