    next: usize,
}

// Entries live in a vector (slots). For every count, the entries with that count form a doubly
// linked list through their slots, oldest use first.
struct LFUCache {
    cap: usize,
    min_freq: i32,
    entries: Vec<LfuEntry>,
    free: Vec<usize>,                   // slots of evicted entries, ready to reuse
    slot_of: HashMap<i32, usize>,       // key -> slot
    ends: HashMap<i32, (usize, usize)>, // count -> (first slot, last slot) of its list
}

impl LFUCache {
    fn new(capacity: i32) -> Self {
        LFUCache {
            cap: capacity as usize,
            min_freq: 0,
            entries: Vec::new(),
            free: Vec::new(),
            slot_of: HashMap::new(),
            ends: HashMap::new(),
        }
    }

    // Removes the slot from the list of its count; returns true if that list is now empty.
    fn unlink(&mut self, slot: usize) -> bool {
        let (p, n, f) = (self.entries[slot].prev, self.entries[slot].next, self.entries[slot].freq);
        if p != LFU_NIL {
            self.entries[p].next = n;
        }
        if n != LFU_NIL {
            self.entries[n].prev = p;
        }
        let (first, last) = self.ends[&f];
        if first == slot && last == slot {
            self.ends.remove(&f);
            return true;
        }
        let new_first = if first == slot { n } else { first };
        let new_last = if last == slot { p } else { last };
        self.ends.insert(f, (new_first, new_last));
        false
    }

    // Appends the slot at the end (newest) of the list of its count.
    fn push_back(&mut self, slot: usize) {
        let f = self.entries[slot].freq;
        self.entries[slot].next = LFU_NIL;
        match self.ends.get(&f).copied() {
            None => {
                self.entries[slot].prev = LFU_NIL;
                self.ends.insert(f, (slot, slot));
            }
            Some((first, last)) => {
                self.entries[slot].prev = last;
                self.entries[last].next = slot;
                self.ends.insert(f, (first, slot));
            }
        }
    }

    // One more use: the entry moves to the end of the list of count + 1.
    fn touch(&mut self, slot: usize) {
        let f = self.entries[slot].freq;
        if self.unlink(slot) && self.min_freq == f {
            self.min_freq = f + 1;
        }
        self.entries[slot].freq = f + 1;
        self.push_back(slot);
    }

    fn get(&mut self, key: i32) -> i32 {
        match self.slot_of.get(&key).copied() {
            None => -1,
            Some(slot) => {
                self.touch(slot);
                self.entries[slot].value
            }
        }
    }

    fn put(&mut self, key: i32, value: i32) {
        if self.cap == 0 {
            return;
        }
        if let Some(&slot) = self.slot_of.get(&key) {
            self.entries[slot].value = value;
            self.touch(slot);
            return;
        }
        if self.slot_of.len() == self.cap {
            // evict the oldest entry of the lowest count
            let victim = self.ends[&self.min_freq].0;
            self.unlink(victim);
            let victim_key = self.entries[victim].key;
            self.slot_of.remove(&victim_key);
            self.free.push(victim);
        }
        let entry = LfuEntry { key, value, freq: 1, prev: LFU_NIL, next: LFU_NIL };
        let slot = match self.free.pop() {
            Some(s) => {
                self.entries[s] = entry;
                s
            }
            None => {
                self.entries.push(entry);
                self.entries.len() - 1
            }
        };
        self.slot_of.insert(key, slot);
        self.push_back(slot);
        self.min_freq = 1;
    }
}

