import scala.collection.mutable

class LFUCache(_capacity: Int) {
  private val values = mutable.HashMap[Int, Int]() // key -> value
  private val counts = mutable.HashMap[Int, Int]() // key -> use count
  // count -> keys with that count, oldest use first (a linked hash set keeps insertion order)
  private val buckets = mutable.HashMap[Int, java.util.LinkedHashSet[Int]]()
  private var minFreq = 0

  private def addToBucket(count: Int, key: Int): Unit = {
    buckets.getOrElseUpdate(count, new java.util.LinkedHashSet[Int]()).add(key)
  }

  // one more use: the key moves from the bucket of f to the end of the bucket of f + 1
  private def touch(key: Int): Unit = {
    val f = counts(key)
    val bucket = buckets(f)
    bucket.remove(key)
    if (bucket.isEmpty) {
      buckets.remove(f)
      if (minFreq == f) minFreq = f + 1
    }
    counts(key) = f + 1
    addToBucket(f + 1, key)
  }

  def get(key: Int): Int = {
    if (!values.contains(key)) {
      -1
    } else {
      touch(key)
      values(key)
    }
  }

  def put(key: Int, value: Int): Unit = {
    if (_capacity > 0) {
      if (values.contains(key)) {
        values(key) = value
        touch(key)
      } else {
        if (values.size >= _capacity) {
          // evict the oldest key of the lowest count
          val bucket = buckets(minFreq)
          val victim = bucket.iterator.next()
          bucket.remove(victim)
          if (bucket.isEmpty) buckets.remove(minFreq)
          values.remove(victim)
          counts.remove(victim)
        }
        values(key) = value
        counts(key) = 1
        addToBucket(1, key)
        minFreq = 1
      }
    }
  }
}

