class RandomizedSet:
    def __init__(self):
        self.items = []  # the values, in any order
        self.pos = {}  # value -> its index in items

    def insert(self, value: int) -> bool:
        if value in self.pos:
            return False
        self.pos[value] = len(self.items)
        self.items.append(value)
        return True

    def remove(self, value: int) -> bool:
        if value not in self.pos:
            return False
        idx = self.pos.pop(value)
        last = self.items.pop()
        if idx < len(self.items):  # the removed value was not the last one:
            self.items[idx] = last  # move the last value into the freed slot
            self.pos[last] = idx
        return True

    def get_random(self) -> int:
        return random.choice(self.items)

