type RandomizedSet struct {
	items []int       // the values, in any order
	pos   map[int]int // value -> its index in items
}

func Constructor() RandomizedSet {
	return RandomizedSet{pos: map[int]int{}}
}

func (this *RandomizedSet) Insert(value int) bool {
	if _, ok := this.pos[value]; ok {
		return false
	}
	this.pos[value] = len(this.items)
	this.items = append(this.items, value)
	return true
}

func (this *RandomizedSet) Remove(value int) bool {
	idx, ok := this.pos[value]
	if !ok {
		return false
	}
	// move the last value into the freed slot, then drop the last slot
	last := this.items[len(this.items)-1]
	this.items[idx] = last
	this.pos[last] = idx
	this.items = this.items[:len(this.items)-1]
	delete(this.pos, value)
	return true
}

func (this *RandomizedSet) GetRandom() int {
	return this.items[rand.Intn(len(this.items))]
}

