class RandomizedSet {
    vector<int> items;                 // the values, in any order
    unordered_map<int, int> pos;       // value -> its index in items

public:
    RandomizedSet() {}

    bool insert(int val) {
        if (pos.count(val)) return false;
        pos[val] = items.size();
        items.push_back(val);
        return true;
    }

    bool remove(int val) {
        auto it = pos.find(val);
        if (it == pos.end()) return false;
        // move the last value into the freed slot, then drop the last slot
        int idx = it->second, last = items.back();
        items[idx] = last;
        pos[last] = idx;
        items.pop_back();
        pos.erase(val);
        return true;
    }

    int getRandom() {
        return items[rand() % items.size()];
    }
};

