use std::collections::hash_map::RandomState;
use std::collections::HashMap;
use std::hash::{BuildHasher, Hasher};

struct RandomizedSet {
    items: Vec<i32>,           // the values, in any order
    pos: HashMap<i32, usize>,  // value -> its index in items
}

impl RandomizedSet {
    fn new() -> Self {
        RandomizedSet { items: Vec::new(), pos: HashMap::new() }
    }

    fn insert(&mut self, value: i32) -> bool {
        if self.pos.contains_key(&value) {
            return false;
        }
        self.pos.insert(value, self.items.len());
        self.items.push(value);
        true
    }

    fn remove(&mut self, value: i32) -> bool {
        match self.pos.remove(&value) {
            None => false,
            Some(idx) => {
                // move the last value into the freed slot, then drop the last slot
                let last = *self.items.last().unwrap();
                self.items.swap_remove(idx);
                if idx < self.items.len() {
                    self.pos.insert(last, idx);
                }
                true
            }
        }
    }

    fn get_random(&self) -> i32 {
        // std has no random numbers; a fresh RandomState gives a random 64-bit value
        let r = RandomState::new().build_hasher().finish() as usize;
        self.items[r % self.items.len()]
    }
}

