function runTwitter(ops, args) {
  let clock = 0;
  const tweets = new Map();
  const follows = new Map();
  return ops.map((op, i) => {
    if (op === 'postTweet') {
      const [u, id] = args[i];
      if (!tweets.has(u)) tweets.set(u, []);
      tweets.get(u).push([clock++, id]);
      return null;
    }
    if (op === 'follow') {
      const [a, b] = args[i];
      if (a === b) return null;
      if (!follows.has(a)) follows.set(a, new Set());
      follows.get(a).add(b);
      return null;
    }
    if (op === 'unfollow') {
      const [a, b] = args[i];
      if (follows.has(a)) follows.get(a).delete(b);
      return null;
    }
    if (op === 'getNewsFeed') {
      const u = args[i][0];
      const people = [u, ...(follows.get(u) || [])];
      const candidates = [];
      for (const p of people) {
        const list = tweets.get(p) || [];
        for (const t of list.slice(-10)) candidates.push(t);
      }
      candidates.sort((x, y) => y[0] - x[0]);
      return candidates.slice(0, 10).map(t => t[1]);
    }
    return null;
  });
