from collections import defaultdict


class Twitter:
    def __init__(self):
        self.clock = 0  # grows with every tweet, so a larger time means a newer tweet
        self.tweets = defaultdict(list)  # user -> [(time, tweet id)] in posting order
        self.follows = defaultdict(set)  # user -> the users they follow

    def post_tweet(self, user_id: int, tweet_id: int) -> None:
        self.tweets[user_id].append((self.clock, tweet_id))
        self.clock += 1

    def get_news_feed(self, user_id: int) -> list[int]:
        candidates = []
        for person in self.follows[user_id] | {user_id}:
            # nobody can add more than their 10 newest tweets to the top 10
            candidates.extend(self.tweets[person][-10:])
        candidates.sort(reverse=True)  # newest first
        return [tweet_id for _, tweet_id in candidates[:10]]

    def follow(self, follower_id: int, followee_id: int) -> None:
        if follower_id != followee_id:
            self.follows[follower_id].add(followee_id)

    def unfollow(self, follower_id: int, followee_id: int) -> None:
        self.follows[follower_id].discard(followee_id)

