import "sort"

type tweetRecord struct{ time, id int }

type Twitter struct {
	clock   int                    // grows with every tweet, so a larger time means a newer tweet
	tweets  map[int][]tweetRecord  // user -> their tweets in posting order
	follows map[int]map[int]bool   // user -> the users they follow
}

func Constructor() Twitter {
	return Twitter{tweets: map[int][]tweetRecord{}, follows: map[int]map[int]bool{}}
}

func (this *Twitter) PostTweet(userId int, tweetId int) {
	this.tweets[userId] = append(this.tweets[userId], tweetRecord{this.clock, tweetId})
	this.clock++
}

func (this *Twitter) GetNewsFeed(userId int) []int {
	people := []int{userId}
	for followee := range this.follows[userId] {
		people = append(people, followee)
	}
	candidates := []tweetRecord{}
	for _, person := range people {
		mine := this.tweets[person]
		if len(mine) > 10 {
			mine = mine[len(mine)-10:] // nobody can add more than their 10 newest tweets
		}
		candidates = append(candidates, mine...)
	}
	sort.Slice(candidates, func(i, j int) bool { return candidates[i].time > candidates[j].time }) // newest first
	if len(candidates) > 10 {
		candidates = candidates[:10]
	}
	feed := []int{}
	for _, t := range candidates {
		feed = append(feed, t.id)
	}
	return feed
}

func (this *Twitter) Follow(followerId int, followeeId int) {
	if followerId == followeeId {
		return
	}
	if this.follows[followerId] == nil {
		this.follows[followerId] = map[int]bool{}
	}
	this.follows[followerId][followeeId] = true
}

func (this *Twitter) Unfollow(followerId int, followeeId int) {
	delete(this.follows[followerId], followeeId) // deleting from a missing map does nothing
}

