use std::collections::{HashMap, HashSet};

struct Twitter {
    clock: i32,                             // grows with every tweet, so a larger time means a newer tweet
    tweets: HashMap<i32, Vec<(i32, i32)>>,  // user -> (time, tweet id) in posting order
    follows: HashMap<i32, HashSet<i32>>,    // user -> the users they follow
}

impl Twitter {
    fn new() -> Self {
        Twitter { clock: 0, tweets: HashMap::new(), follows: HashMap::new() }
    }

    fn post_tweet(&mut self, user_id: i32, tweet_id: i32) {
        self.tweets.entry(user_id).or_default().push((self.clock, tweet_id));
        self.clock += 1;
    }

    fn get_news_feed(&self, user_id: i32) -> Vec<i32> {
        let mut people = vec![user_id];
        if let Some(followees) = self.follows.get(&user_id) {
            people.extend(followees.iter().copied());
        }
        let mut candidates: Vec<(i32, i32)> = Vec::new();
        for person in people {
            if let Some(mine) = self.tweets.get(&person) {
                // nobody can add more than their 10 newest tweets
                let from = mine.len().saturating_sub(10);
                candidates.extend_from_slice(&mine[from..]);
            }
        }
        candidates.sort_by(|a, b| b.0.cmp(&a.0)); // newest first
        candidates.iter().take(10).map(|&(_, id)| id).collect()
    }

    fn follow(&mut self, follower_id: i32, followee_id: i32) {
        if follower_id != followee_id {
            self.follows.entry(follower_id).or_default().insert(followee_id);
        }
    }

    fn unfollow(&mut self, follower_id: i32, followee_id: i32) {
        if let Some(followees) = self.follows.get_mut(&follower_id) {
            followees.remove(&followee_id);
        }
    }
}

