import scala.collection.mutable

class Twitter() {
  private var clock = 0 // grows with every tweet, so a larger time means a newer tweet
  // user -> (time, tweet id) in posting order
  private val tweets = mutable.HashMap[Int, mutable.ArrayBuffer[(Int, Int)]]()
  // user -> the users they follow
  private val follows = mutable.HashMap[Int, mutable.HashSet[Int]]()

  def postTweet(userId: Int, tweetId: Int): Unit = {
    tweets.getOrElseUpdate(userId, mutable.ArrayBuffer[(Int, Int)]()) += ((clock, tweetId))
    clock += 1
  }

  def getNewsFeed(userId: Int): Array[Int] = {
    val people = follows.getOrElse(userId, mutable.HashSet[Int]()).toList :+ userId
    val candidates = mutable.ArrayBuffer[(Int, Int)]()
    for (person <- people) {
      // nobody can add more than their 10 newest tweets
      candidates ++= tweets.getOrElse(person, mutable.ArrayBuffer[(Int, Int)]()).takeRight(10)
    }
    // newest first
    candidates.sortBy(t => -t._1).take(10).map(t => t._2).toArray
  }

  def follow(followerId: Int, followeeId: Int): Unit = {
    if (followerId != followeeId) {
      follows.getOrElseUpdate(followerId, mutable.HashSet[Int]()) += followeeId
    }
  }

  def unfollow(followerId: Int, followeeId: Int): Unit = {
    follows.get(followerId) match {
      case Some(followees) => followees.remove(followeeId)
      case None            => ()
    }
  }
