    if (op === 'inc') {
      const k = args[i][0];
      const cur = where.get(k) || head;
      let nxt = cur.next;
      if (nxt.cnt !== cur.cnt + 1) nxt = insertAfter(cur, cur.cnt + 1);
      nxt.keys.add(k);
      where.set(k, nxt);
      if (cur !== head) {
        cur.keys.delete(k);
        dropIfEmpty(cur);
      }
      return null;
    }
    if (op === 'dec') {
      const k = args[i][0];
      const cur = where.get(k);
      if (cur.cnt === 1) {
        where.delete(k);
      } else {
        let prv = cur.prev;
        if (prv.cnt !== cur.cnt - 1) prv = insertAfter(prv, cur.cnt - 1);
        prv.keys.add(k);
        where.set(k, prv);
      }
      cur.keys.delete(k);
      dropIfEmpty(cur);
      return null;
    }
    if (op === 'getMaxKey') {
      return tail.prev === head ? '' : tail.prev.keys.values().next().value;
    }
    if (op === 'getMinKey') {
      return head.next === tail ? '' : head.next.keys.values().next().value;
    }
    return null;
  });
}

