class AllOneBucket:
    """All keys with the same count; buckets form a doubly linked list sorted by count."""

    def __init__(self, count: int):
        self.count = count
        self.keys = set()
        self.prev = None
        self.next = None


class AllOne:
    def __init__(self):
        self.head = AllOneBucket(0)  # sentinel before the smallest count
        self.tail = AllOneBucket(float("inf"))  # sentinel after the largest count
        self.head.next = self.tail
        self.tail.prev = self.head
        self.bucket_of = {}  # key -> its bucket

    def _insert_after(self, bucket: AllOneBucket, count: int) -> AllOneBucket:
        new = AllOneBucket(count)
        new.prev, new.next = bucket, bucket.next
        bucket.next.prev = new
        bucket.next = new
        return new

    def _drop_if_empty(self, bucket: AllOneBucket) -> None:
        if bucket is not self.head and not bucket.keys:
            bucket.prev.next = bucket.next
            bucket.next.prev = bucket.prev

    def inc(self, key: str) -> None:
        cur = self.bucket_of.get(key, self.head)  # a new key starts at the head (count 0)
        nxt = cur.next
        if nxt.count != cur.count + 1:
            nxt = self._insert_after(cur, cur.count + 1)
        nxt.keys.add(key)
        self.bucket_of[key] = nxt
        if cur is not self.head:
            cur.keys.discard(key)
            self._drop_if_empty(cur)

    def dec(self, key: str) -> None:
        cur = self.bucket_of[key]
        if cur.count == 1:
            del self.bucket_of[key]  # count 0: the key disappears
        else:
            prv = cur.prev
            if prv.count != cur.count - 1:
                prv = self._insert_after(prv, cur.count - 1)
            prv.keys.add(key)
            self.bucket_of[key] = prv
        cur.keys.discard(key)
        self._drop_if_empty(cur)

    def get_max_key(self) -> str:
        last = self.tail.prev
        return "" if last is self.head else next(iter(last.keys))

    def get_min_key(self) -> str:
        first = self.head.next
        return "" if first is self.tail else next(iter(first.keys))

