func Constructor() AllOne {
	head := &allOneBucket{count: 0, keys: map[string]bool{}}
	tail := &allOneBucket{count: 1 << 60, keys: map[string]bool{}}
	head.next = tail
	tail.prev = head
	return AllOne{head: head, tail: tail, bucketOf: map[string]*allOneBucket{}}
}

func (this *AllOne) insertAfter(b *allOneBucket, count int) *allOneBucket {
	nb := &allOneBucket{count: count, keys: map[string]bool{}, prev: b, next: b.next}
	b.next.prev = nb
	b.next = nb
	return nb
}

func (this *AllOne) dropIfEmpty(b *allOneBucket) {
	if b != this.head && len(b.keys) == 0 {
		b.prev.next = b.next
		b.next.prev = b.prev
	}
}

func (this *AllOne) Inc(key string) {
	cur, ok := this.bucketOf[key]
	if !ok {
		cur = this.head // a new key starts at the head (count 0)
	}
	nxt := cur.next
	if nxt.count != cur.count+1 {
		nxt = this.insertAfter(cur, cur.count+1)
	}
	nxt.keys[key] = true
	this.bucketOf[key] = nxt
	if cur != this.head {
		delete(cur.keys, key)
		this.dropIfEmpty(cur)
	}
}

func (this *AllOne) Dec(key string) {
	cur := this.bucketOf[key]
	if cur.count == 1 {
		delete(this.bucketOf, key) // count 0: the key disappears
	} else {
		prv := cur.prev
		if prv.count != cur.count-1 {
			prv = this.insertAfter(prv, cur.count-1)
		}
