class AllOne {
    // all keys with the same count; buckets form a doubly linked list sorted by count
    struct Bucket {
        int count;
        unordered_set<string> keys;
        Bucket *prev = nullptr, *next = nullptr;
        Bucket(int c) : count(c) {}
    };
    Bucket *head, *tail;  // sentinels: count 0 before the smallest, a huge count after the largest
    unordered_map<string, Bucket*> bucketOf;

    Bucket* insertAfter(Bucket* b, int count) {
        Bucket* nb = new Bucket(count);
        nb->prev = b;
        nb->next = b->next;
        b->next->prev = nb;
        b->next = nb;
        return nb;
    }

    void dropIfEmpty(Bucket* b) {
        if (b != head && b->keys.empty()) {
            b->prev->next = b->next;
            b->next->prev = b->prev;
            delete b;
        }
    }

public:
    AllOne() {
        head = new Bucket(0);
        tail = new Bucket(INT_MAX);
        head->next = tail;
        tail->prev = head;
    }

    ~AllOne() {
        while (head) {
            Bucket* next = head->next;
            delete head;
            head = next;
        }
    }

    void inc(string key) {
        auto it = bucketOf.find(key);
        Bucket* cur = it == bucketOf.end() ? head : it->second;  // a new key starts at the head (count 0)
        Bucket* nxt = cur->next;
        if (nxt->count != cur->count + 1) nxt = insertAfter(cur, cur->count + 1);
        nxt->keys.insert(key);
        bucketOf[key] = nxt;
        if (cur != head) {
            cur->keys.erase(key);
            dropIfEmpty(cur);
        }
    }

    void dec(string key) {
        Bucket* cur = bucketOf[key];
        if (cur->count == 1) {
            bucketOf.erase(key);  // count 0: the key disappears
        } else {
            Bucket* prv = cur->prev;
            if (prv->count != cur->count - 1) prv = insertAfter(prv, cur->count - 1);
            prv->keys.insert(key);
            bucketOf[key] = prv;
        }
        cur->keys.erase(key);
        dropIfEmpty(cur);
    }

    string getMaxKey() {
        Bucket* last = tail->prev;
        return last == head ? "" : *last->keys.begin();
    }

    string getMinKey() {
        Bucket* first = head->next;
        return first == tail ? "" : *first->keys.begin();
    }
};

