use std::collections::{HashMap, HashSet};

// All keys with the same count. Buckets live in a vector and are linked by index, sorted by count.
struct AllOneBucket {
    count: i32,
    keys: HashSet<String>,
    prev: usize,
    next: usize,
}

struct AllOne {
    buckets: Vec<AllOneBucket>, // slot 0 = head sentinel (count 0), slot 1 = tail sentinel (huge count)
    free: Vec<usize>,           // slots of dropped buckets, ready to reuse
    bucket_of: HashMap<String, usize>, // key -> its bucket
}

impl AllOne {
    const HEAD: usize = 0;
    const TAIL: usize = 1;

    fn new() -> Self {
        let head = AllOneBucket { count: 0, keys: HashSet::new(), prev: Self::TAIL, next: Self::TAIL };
        let tail = AllOneBucket { count: i32::MAX, keys: HashSet::new(), prev: Self::HEAD, next: Self::HEAD };
        AllOne { buckets: vec![head, tail], free: Vec::new(), bucket_of: HashMap::new() }
    }

    // Creates a bucket with this count and links it right after `after`.
    fn insert_after(&mut self, after: usize, count: i32) -> usize {
        let next = self.buckets[after].next;
        let bucket = AllOneBucket { count, keys: HashSet::new(), prev: after, next };
        let id = match self.free.pop() {
            Some(id) => {
                self.buckets[id] = bucket;
                id
            }
            None => {
                self.buckets.push(bucket);
                self.buckets.len() - 1
            }
        };
        self.buckets[next].prev = id;
        self.buckets[after].next = id;
        id
    }

    fn drop_if_empty(&mut self, id: usize) {
        if id != Self::HEAD && self.buckets[id].keys.is_empty() {
            let (p, n) = (self.buckets[id].prev, self.buckets[id].next);
            self.buckets[p].next = n;
            self.buckets[n].prev = p;
            self.free.push(id);
        }
    }

    fn inc(&mut self, key: String) {
        // a new key starts at the head (count 0)
        let cur = self.bucket_of.get(&key).copied().unwrap_or(Self::HEAD);
        let count = self.buckets[cur].count;
        let mut nxt = self.buckets[cur].next;
        if self.buckets[nxt].count != count + 1 {
            nxt = self.insert_after(cur, count + 1);
        }
        self.buckets[nxt].keys.insert(key.clone());
        self.bucket_of.insert(key.clone(), nxt);
        if cur != Self::HEAD {
            self.buckets[cur].keys.remove(&key);
            self.drop_if_empty(cur);
        }
    }

    fn dec(&mut self, key: String) {
        let cur = self.bucket_of[&key];
        let count = self.buckets[cur].count;
        if count == 1 {
            self.bucket_of.remove(&key); // count 0: the key disappears
        } else {
            let mut prv = self.buckets[cur].prev;
            if self.buckets[prv].count != count - 1 {
                prv = self.insert_after(prv, count - 1);
            }
            self.buckets[prv].keys.insert(key.clone());
            self.bucket_of.insert(key.clone(), prv);
        }
        self.buckets[cur].keys.remove(&key);
        self.drop_if_empty(cur);
    }

    fn get_max_key(&self) -> String {
        let last = self.buckets[Self::TAIL].prev;
        if last == Self::HEAD {
            return String::new();
        }
        self.buckets[last].keys.iter().next().cloned().unwrap_or_default()
    }

    fn get_min_key(&self) -> String {
        let first = self.buckets[Self::HEAD].next;
        if first == Self::TAIL {
            return String::new();
        }
        self.buckets[first].keys.iter().next().cloned().unwrap_or_default()
    }
}

