import scala.collection.mutable

class AllOne() {
  // all keys with the same count; buckets form a doubly linked list sorted by count
  private class Bucket(val count: Int) {
    val keys = mutable.HashSet[String]()
    var prev: Bucket = null
    var next: Bucket = null
  }

  private val head = new Bucket(0) // sentinel before the smallest count
  private val tail = new Bucket(Int.MaxValue) // sentinel after the largest count
  head.next = tail
  tail.prev = head
  private val bucketOf = mutable.HashMap[String, Bucket]()

  private def insertAfter(b: Bucket, count: Int): Bucket = {
    val nb = new Bucket(count)
    nb.prev = b
    nb.next = b.next
    b.next.prev = nb
    b.next = nb
    nb
  }

  private def dropIfEmpty(b: Bucket): Unit = {
    if (b != head && b.keys.isEmpty) {
      b.prev.next = b.next
      b.next.prev = b.prev
    }
  }

  def inc(key: String): Unit = {
    val cur = bucketOf.getOrElse(key, head) // a new key starts at the head (count 0)
    var nxt = cur.next
    if (nxt.count != cur.count + 1) nxt = insertAfter(cur, cur.count + 1)
    nxt.keys += key
    bucketOf(key) = nxt
    if (cur != head) {
      cur.keys -= key
      dropIfEmpty(cur)
    }
  }

  def dec(key: String): Unit = {
    val cur = bucketOf(key)
    if (cur.count == 1) {
      bucketOf.remove(key) // count 0: the key disappears
    } else {
      var prv = cur.prev
      if (prv.count != cur.count - 1) prv = insertAfter(prv, cur.count - 1)
      prv.keys += key
      bucketOf(key) = prv
    }
    cur.keys -= key
    dropIfEmpty(cur)
  }

  def getMaxKey(): String = {
    if (tail.prev == head) "" else tail.prev.keys.head
  }

  def getMinKey(): String = {
    if (head.next == tail) "" else head.next.keys.head
  }
}

