function removeKdigits(num, k) {
  const stack = [];
  for (const d of num) {
    while (k > 0 && stack.length && stack[stack.length - 1] > d) {
      stack.pop();
      k--;
    }
    stack.push(d);
  }
  while (k > 0) {
    stack.pop();
    k--;
  }
  let start = 0;
  while (start < stack.length && stack[start] === '0') start++;
  const res = stack.slice(start).join('');
  return res === '' ? '0' : res;
}

