def remove_kdigits(num: str, k: int) -> str:
    stack = []  # digits kept so far, never decreasing unless we ran out of removals
    for d in num:
        # a bigger digit just before a smaller one is worth removing
        while k > 0 and stack and stack[-1] > d:
            stack.pop()
            k -= 1
        stack.append(d)
    stack = stack[:len(stack) - k]  # removals left over: drop the largest digits at the end
    return "".join(stack).lstrip("0") or "0"

