func sumSubarrayMins(arr []int) int {
	const mod = 1_000_000_007
	n := len(arr)
	left := make([]int, n)  // how many subarrays can start at or before i with arr[i] as their minimum
	right := make([]int, n) // how many can end at or after i
	var stack []int
	for i := 0; i < n; i++ {
		for len(stack) > 0 && arr[stack[len(stack)-1]] > arr[i] {
			stack = stack[:len(stack)-1]
		}
		if len(stack) > 0 {
			left[i] = i - stack[len(stack)-1]
		} else {
			left[i] = i + 1
		}
		stack = append(stack, i)
	}
	stack = stack[:0]
	for i := n - 1; i >= 0; i-- {
		// strict on one side, non-strict on the other, so ties are counted once
		for len(stack) > 0 && arr[stack[len(stack)-1]] >= arr[i] {
			stack = stack[:len(stack)-1]
		}
		if len(stack) > 0 {
			right[i] = stack[len(stack)-1] - i
		} else {
			right[i] = n - i
		}
		stack = append(stack, i)
	}
	total := 0
	for i := 0; i < n; i++ {
		total = (total + arr[i]*left[i]*right[i]) % mod
	}
	return total
}

