    pub fn sum_subarray_mins(arr: Vec<i32>) -> i32 {
        const MOD: i64 = 1_000_000_007;
        let n = arr.len();
        let mut left = vec![0i64; n]; // subarrays that can start at or before i with arr[i] as minimum
        let mut right = vec![0i64; n]; // subarrays that can end at or after i
        let mut stack: Vec<usize> = Vec::new();
        for i in 0..n {
            while let Some(&j) = stack.last() {
                if arr[j] <= arr[i] {
                    break;
                }
                stack.pop();
            }
            left[i] = match stack.last() {
                Some(&j) => (i - j) as i64,
                None => (i + 1) as i64,
            };
            stack.push(i);
        }
        stack.clear();
        for i in (0..n).rev() {
            // strict on one side, non-strict on the other, so ties are counted once
            while let Some(&j) = stack.last() {
                if arr[j] < arr[i] {
                    break;
                }
                stack.pop();
            }
            right[i] = match stack.last() {
                Some(&j) => (j - i) as i64,
                None => (n - i) as i64,
            };
            stack.push(i);
        }
        let mut total = 0i64;
        for i in 0..n {
            total = (total + arr[i] as i64 * left[i] * right[i]) % MOD;
        }
        total as i32
    }
