object Solution {
  def sumSubarrayMins(arr: Array[Int]): Int = {
    val MOD = 1000000007L
    val n = arr.length
    val left = new Array[Long](n)  // subarrays that can start at or before i with arr[i] as minimum
    val right = new Array[Long](n) // subarrays that can end at or after i
    val stack = scala.collection.mutable.ArrayBuffer[Int]()
    for (i <- 0 until n) {
      while (stack.nonEmpty && arr(stack.last) > arr(i)) stack.remove(stack.length - 1)
      left(i) = if (stack.isEmpty) i + 1 else i - stack.last
      stack += i
    }
    stack.clear()
    for (i <- n - 1 to 0 by -1) {
      // strict on one side, non-strict on the other, so ties are counted once
      while (stack.nonEmpty && arr(stack.last) >= arr(i)) stack.remove(stack.length - 1)
      right(i) = if (stack.isEmpty) n - i else stack.last - i
      stack += i
    }
    var total = 0L
    for (i <- 0 until n) {
      total = (total + arr(i).toLong * left(i) * right(i)) % MOD
    }
    total.toInt
  }
