    var num = 0
    var op = '+' // the operator that came before num
    for (ch <- s + "+") { // the extra "+" flushes the last number
      if (ch.isDigit) {
        num = num * 10 + (ch - '0')
      } else if (ch != ' ') {
        if (op == '+') terms += num
        else if (op == '-') terms += -num
        else if (op == '*') terms(terms.length - 1) = terms.last * num
        else terms(terms.length - 1) = terms.last / num // Scala truncates toward zero
        op = ch
        num = 0
      }
    }
    terms.sum
  }
}

