function searchRange(nums, target) {
  const firstAtLeast = t => {
    let lo = 0, hi = nums.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (nums[mid] >= t) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  };
  const left = firstAtLeast(target);
  if (left === nums.length || nums[left] !== target) return [-1, -1];
  return [left, firstAtLeast(target + 1) - 1];
}

