func minSubArrayLen(target int, nums []int) int {
	none := len(nums) + 1 // larger than any real window
	best := none
	sum, left := 0, 0
	for right, x := range nums {
		sum += x
		for sum >= target { // shrink while the window is still big enough
			if right-left+1 < best {
				best = right - left + 1
			}
			sum -= nums[left]
			left++
		}
	}
	if best == none {
		return 0
	}
	return best
}

