function findAnagrams(s, p) {
  const res = [];
  if (p.length > s.length) return res;
  const need = new Array(26).fill(0);
  const code = c => c.charCodeAt(0) - 97;
  for (const c of p) need[code(c)]++;
  let nonZero = 0;
  for (const x of need) if (x !== 0) nonZero++;
  const change = (idx, delta) => {
    if (need[idx] === 0) nonZero++;
    need[idx] += delta;
    if (need[idx] === 0) nonZero--;
  };
  for (let i = 0; i < s.length; i++) {
    change(code(s[i]), -1);
    if (i >= p.length) change(code(s[i - p.length]), 1);
    if (i >= p.length - 1 && nonZero === 0) res.push(i - p.length + 1);
  }
  return res;
}

