func findAnagrams(s string, p string) []int {
	var need, win [26]int // letter counts of p, and of the current window of s
	for i := 0; i < len(p); i++ {
		need[p[i]-'a']++
	}
	res := []int{}
	for i := 0; i < len(s); i++ {
		win[s[i]-'a']++
		if i >= len(p) { // the window is full: drop the letter that slides out
			win[s[i-len(p)]-'a']--
		}
		if win == need { // arrays compare element by element
			res = append(res, i-len(p)+1)
		}
	}
	return res
}

