    if (!node) return 0;
    const good = node.val >= maxSoFar ? 1 : 0;
    const m = Math.max(maxSoFar, node.val);
    return good + dfs(node.left, m) + dfs(node.right, m);
  };
  return dfs(root, -Infinity);
}

