        *p += 1;
        let mid = pos[&val];
        let node = Rc::new(RefCell::new(TreeNode::new(val)));
        node.borrow_mut().left = Self::build(preorder, pos, p, lo, mid - 1);
        node.borrow_mut().right = Self::build(preorder, pos, p, mid + 1, hi);
        Some(node)
    }
}

