use std::cell::RefCell;
use std::rc::Rc;

impl Solution {
    pub fn lowest_common_ancestor(root: Option<Rc<RefCell<TreeNode>>>, p: i32, q: i32) -> i32 {
        let mut cur = root;
        while let Some(node) = cur {
            let val = node.borrow().val;
            if p < val && q < val {
                cur = node.borrow().left.clone(); // both are in the left subtree
            } else if p > val && q > val {
                cur = node.borrow().right.clone(); // both are in the right subtree
            } else {
                return val; // the paths split here (or one of them is node)
            }
        }
        -1
    }
}

