function buildTree(a) {
  if (!a.length || a[0] === null) return null;
  const root = { val: a[0], left: null, right: null }, q = [root]; let i = 1;
  while (q.length && i < a.length) {
    const n = q.shift();
    if (i < a.length && a[i] !== null) { n.left = { val: a[i], left: null, right: null }; q.push(n.left); } i++;
    if (i < a.length && a[i] !== null) { n.right = { val: a[i], left: null, right: null }; q.push(n.right); } i++;
  }
  return root;
}
function treeToArray(root) {
  const out = [], q = [root];
  for (let i = 0; i < q.length; i++) {
    const n = q[i];
    if (n) { out.push(n.val); q.push(n.left, n.right); } else out.push(null);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return out;
}
function deleteNode(tree, key) {
    const del = (node, k) => {
      if (!node) return null;
      if (k < node.val) node.left = del(node.left, k);
      else if (k > node.val) node.right = del(node.right, k);
      else {
        if (!node.left) return node.right;
        if (!node.right) return node.left;
        let succ = node.right;
        while (succ.left) succ = succ.left;
        node.val = succ.val;
        node.right = del(node.right, succ.val);
      }
      return node;
    };
    return treeToArray(del(buildTree(tree), key));
