use std::cell::RefCell;
use std::rc::Rc;

impl Solution {
    pub fn delete_node(root: Option<Rc<RefCell<TreeNode>>>, key: i32) -> Option<Rc<RefCell<TreeNode>>> {
        let node = root?;
        let val = node.borrow().val;
        if key < val {
            let left = node.borrow_mut().left.take();
            node.borrow_mut().left = Self::delete_node(left, key);
        } else if key > val {
            let right = node.borrow_mut().right.take();
            node.borrow_mut().right = Self::delete_node(right, key);
        } else {
            let left = node.borrow_mut().left.take();
            let right = node.borrow_mut().right.take();
            if left.is_none() {
                return right; // zero or one child: the child takes this place
            }
            if right.is_none() {
                return left;
            }
            // two children: copy the inorder successor, then delete it below
            let mut succ = right.clone().unwrap();
            loop {
                let next = succ.borrow().left.clone();
                match next {
                    Some(n) => succ = n,
                    None => break,
                }
            }
            let succ_val = succ.borrow().val;
            node.borrow_mut().val = succ_val;
            node.borrow_mut().left = left;
            node.borrow_mut().right = Self::delete_node(right, succ_val);
        }
        Some(node)
    }
}

