import scala.collection.mutable.ArrayBuffer

object Solution {
  def subsetsWithDup(nums: Array[Int]): Array[Array[Int]] = {
    val sorted = nums.sorted // equal numbers become neighbours
    val res = ArrayBuffer[Array[Int]]()
    val path = ArrayBuffer[Int]()
    def dfs(start: Int): Unit = {
      res += path.toArray
      for (i <- start until sorted.length) {
        if (i == start || sorted(i) != sorted(i - 1)) { // skip a value already tried at this depth
          path += sorted(i)
          dfs(i + 1)
          path.remove(path.length - 1)
        }
      }
    }
    dfs(0)
    res.toArray
  }
}

