import scala.collection.mutable.ArrayBuffer

object Solution {
  def permuteUnique(nums: Array[Int]): Array[Array[Int]] = {
    val sorted = nums.sorted
    val res = ArrayBuffer[Array[Int]]()
    val path = ArrayBuffer[Int]()
    val used = new Array[Boolean](sorted.length)
    def dfs(): Unit = {
      if (path.length == sorted.length) {
        res += path.toArray
      } else {
        for (i <- sorted.indices) {
          // equal numbers must be used in sorted order
          val skip = used(i) || (i > 0 && sorted(i) == sorted(i - 1) && !used(i - 1))
          if (!skip) {
            used(i) = true
            path += sorted(i)
            dfs()
            path.remove(path.length - 1)
            used(i) = false
          }
        }
      }
    }
    dfs()
    res.toArray
  }
}

