function restoreIpAddresses(s) {
    const res = [], parts = [];
    const go = (i) => {
      const left = 4 - parts.length;
      const rest = s.length - i;
      if (rest < left || rest > 3 * left) return;
      if (left === 0) { res.push(parts.join('.')); return; }
      for (let len = 1; len <= 3 && i + len <= s.length; len++) {
        const piece = s.slice(i, i + len);
        if (piece.length > 1 && piece[0] === '0') break;
        if (Number(piece) > 255) break;
        parts.push(piece);
        go(i + len);
        parts.pop();
      }
    };
    go(0);
    return res;
  }

