func wallsAndGates(rooms [][]int) [][]int {
	const inf = 2147483647
	m, n := len(rooms), len(rooms[0])
	// multi-source BFS: start from all gates at once
	queue := [][2]int{}
	for r := 0; r < m; r++ {
