use std::collections::VecDeque;

impl Solution {
    pub fn walls_and_gates(mut rooms: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
        const INF: i32 = 2147483647;
        let (m, n) = (rooms.len(), rooms[0].len());
        // multi-source BFS: start from all gates at once
        let mut queue = VecDeque::new();
        for r in 0..m {
            for c in 0..n {
                if rooms[r][c] == 0 {
                    queue.push_back((r, c));
                }
            }
        }
        while let Some((r, c)) = queue.pop_front() {
            for (dr, dc) in [(1i32, 0i32), (-1, 0), (0, 1), (0, -1)] {
                let (nr, nc) = (r as i32 + dr, c as i32 + dc);
                if nr < 0 || nc < 0 || nr >= m as i32 || nc >= n as i32 {
                    continue;
                }
                let (nr, nc) = (nr as usize, nc as usize);
                // a room that is still INF has not been visited yet
                if rooms[nr][nc] == INF {
                    rooms[nr][nc] = rooms[r][c] + 1;
                    queue.push_back((nr, nc));
                }
            }
        }
        rooms
    }
}

