    val INF = 2147483647
    val m = rooms.length
    val n = rooms(0).length
    // multi-source BFS: start from all gates at once
    val queue = mutable.Queue[(Int, Int)]()
    for (r <- 0 until m; c <- 0 until n if rooms(r)(c) == 0) queue.enqueue((r, c))
    val dr = Array(1, -1, 0, 0)
    val dc = Array(0, 0, 1, -1)
    while (queue.nonEmpty) {
      val (r, c) = queue.dequeue()
      for (d <- 0 until 4) {
        val nr = r + dr(d)
        val nc = c + dc(d)
        // a room that is still INF has not been visited yet
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && rooms(nr)(nc) == INF) {
          rooms(nr)(nc) = rooms(r)(c) + 1
          queue.enqueue((nr, nc))
        }
      }
    }
    rooms
  }
}

