def find_min_height_trees(n: int, edges: list[list[int]]) -> list[int]:
    if n <= 2:
        return list(range(n))
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    deg = [len(nbrs) for nbrs in adj]
    leaves = [i for i in range(n) if deg[i] == 1]
    remaining = n
    # peel off the leaves layer by layer; the last 1 or 2 nodes are the centers
    while remaining > 2:
        remaining -= len(leaves)
        next_leaves = []
        for leaf in leaves:
            for v in adj[leaf]:
                deg[v] -= 1
                if deg[v] == 1:
                    next_leaves.append(v)
        leaves = next_leaves
    return leaves

