func findMinHeightTrees(n int, edges [][]int) []int {
	if n <= 2 {
		res := make([]int, n)
		for i := range res {
			res[i] = i
		}
		return res
	}
	adj := make([][]int, n)
	for _, e := range edges {
		adj[e[0]] = append(adj[e[0]], e[1])
		adj[e[1]] = append(adj[e[1]], e[0])
	}
	deg := make([]int, n)
	leaves := []int{}
	for i := range adj {
		deg[i] = len(adj[i])
		if deg[i] == 1 {
			leaves = append(leaves, i)
		}
	}
	remaining := n
	// peel off the leaves layer by layer; the last 1 or 2 nodes are the centers
	for remaining > 2 {
		remaining -= len(leaves)
		next := []int{}
		for _, leaf := range leaves {
			for _, v := range adj[leaf] {
				deg[v]--
				if deg[v] == 1 {
					next = append(next, v)
				}
			}
		}
		leaves = next
	}
	return leaves
}

