function minimumSemesters(n, relations) {
    const adj = Array.from({ length: n + 1 }, () => []);
    const indeg = new Array(n + 1).fill(0);
    for (const [a, b] of relations) { adj[a].push(b); indeg[b]++; }
    let layer = [];
    for (let i = 1; i <= n; i++) if (indeg[i] === 0) layer.push(i);
    let semesters = 0, done = 0;
    while (layer.length) {
      semesters++;
      done += layer.length;
      const next = [];
      for (const u of layer) for (const v of adj[u]) if (--indeg[v] === 0) next.push(v);
      layer = next;
    }
    return done === n ? semesters : -1;
  }

