func minimumSemesters(n int, relations [][]int) int {
	adj := make([][]int, n+1)
	indeg := make([]int, n+1)
	for _, r := range relations { // r[0] before r[1]
		adj[r[0]] = append(adj[r[0]], r[1])
		indeg[r[1]]++
	}
	layer := []int{}
	for i := 1; i <= n; i++ {
		if indeg[i] == 0 {
			layer = append(layer, i)
		}
	}
	semesters, done := 0, 0
	for len(layer) > 0 { // each layer of the topological sort is one semester
		semesters++
		done += len(layer)
		next := []int{}
		for _, u := range layer {
			for _, v := range adj[u] {
				indeg[v]--
				if indeg[v] == 0 {
					next = append(next, v)
				}
			}
		}
		layer = next
	}
	if done != n {
		return -1 // unfinished courses mean a cycle
	}
	return semesters
}

