function findAllRecipes(recipes, ingredients, supplies) {
    const users = new Map(), need = new Map();
    recipes.forEach((r, i) => {
      need.set(r, ingredients[i].length);
      for (const ing of ingredients[i]) {
        if (!users.has(ing)) users.set(ing, []);
        users.get(ing).push(r);
      }
    });
    const queue = [...supplies], out = [];
    for (let i = 0; i < queue.length; i++) {
      for (const r of users.get(queue[i]) || []) {
        need.set(r, need.get(r) - 1);
        if (need.get(r) === 0) { out.push(r); queue.push(r); }
      }
    }
    return out;
  }

