from collections import defaultdict, deque


def find_all_recipes(recipes: list[str], ingredients: list[list[str]], supplies: list[str]) -> list[str]:
    users = defaultdict(list)  # item -> recipes that need it
    need = {}  # recipe -> how many ingredients are still missing
    for recipe, items in zip(recipes, ingredients):
        need[recipe] = len(items)
        for item in items:
            users[item].append(recipe)
    queue = deque(supplies)  # items we have (supplies first, then recipes we can make)
    out = []
    while queue:
        item = queue.popleft()
        for recipe in users[item]:
            need[recipe] -= 1
            if need[recipe] == 0:
                out.append(recipe)
                queue.append(recipe)
    return out

