func findAllRecipes(recipes []string, ingredients [][]string, supplies []string) []string {
	users := map[string][]string{} // item -> recipes that need it
	need := map[string]int{}       // recipe -> how many ingredients are still missing
	for i, recipe := range recipes {
		need[recipe] = len(ingredients[i])
		for _, item := range ingredients[i] {
			users[item] = append(users[item], recipe)
		}
	}
	queue := append([]string{}, supplies...) // items we have (supplies first, then recipes we can make)
	out := []string{}
	for i := 0; i < len(queue); i++ {
		for _, recipe := range users[queue[i]] {
			need[recipe]--
			if need[recipe] == 0 {
				out = append(out, recipe)
				queue = append(queue, recipe)
			}
		}
	}
	return out
}

