class Solution {
public:
    vector<string> findAllRecipes(vector<string>& recipes, vector<vector<string>>& ingredients, vector<string>& supplies) {
        unordered_map<string, vector<string>> users;  // item -> recipes that need it
        unordered_map<string, int> need;              // recipe -> how many ingredients are still missing
        for (size_t i = 0; i < recipes.size(); i++) {
            need[recipes[i]] = ingredients[i].size();
            for (auto& item : ingredients[i]) users[item].push_back(recipes[i]);
        }
        vector<string> queue = supplies;  // items we have (supplies first, then recipes we can make)
        vector<string> out;
        for (size_t i = 0; i < queue.size(); i++) {
            string item = queue[i];
            for (auto& recipe : users[item]) {
                if (--need[recipe] == 0) {
                    out.push_back(recipe);
                    queue.push_back(recipe);
                }
            }
        }
        return out;
    }
};

