use std::collections::HashMap;

impl Solution {
    pub fn find_all_recipes(recipes: Vec<String>, ingredients: Vec<Vec<String>>, supplies: Vec<String>) -> Vec<String> {
        let mut users: HashMap<&str, Vec<usize>> = HashMap::new(); // item -> recipes (by index) that need it
        let mut need = vec![0i32; recipes.len()]; // how many ingredients are still missing
        for (i, items) in ingredients.iter().enumerate() {
            need[i] = items.len() as i32;
            for item in items {
                users.entry(item.as_str()).or_default().push(i);
            }
        }
        // items we have (supplies first, then recipes we can make)
        let mut queue: Vec<&str> = supplies.iter().map(|s| s.as_str()).collect();
        let mut out = Vec::new();
        let mut head = 0;
        while head < queue.len() {
            let item = queue[head];
            head += 1;
            if let Some(list) = users.get(item) {
                for &i in list {
                    need[i] -= 1;
                    if need[i] == 0 {
                        out.push(recipes[i].clone());
                        queue.push(recipes[i].as_str());
                    }
                }
            }
        }
        out
    }
}

