object Solution {
  def sequenceReconstruction(nums: Array[Int], sequences: Array[Array[Int]]): Boolean = {
    val n = nums.length
    val adj = Array.fill(n + 1)(scala.collection.mutable.HashSet[Int]())
    val indeg = new Array[Int](n + 1)
    for (seq <- sequences; i <- 0 until seq.length - 1) { // seq(i) must come before seq(i+1)
      val a = seq(i)
      val b = seq(i + 1)
      if (!adj(a).contains(b)) {
        adj(a) += b
        indeg(b) += 1
      }
    }
    val queue = scala.collection.mutable.ArrayBuffer[Int]()
    for (v <- 1 to n if indeg(v) == 0) queue += v
    var idx = 0
    while (idx < n) {
      // the order is unique only if there is exactly one choice at every step
      if (queue.length != 1) return false
      val u = queue.remove(queue.length - 1)
      if (u != nums(idx)) return false
      for (v <- adj(u)) {
        indeg(v) -= 1
        if (indeg(v) == 0) queue += v
      }
      idx += 1
    }
    true
  }
}

