import "container/heap"

type probItem struct {
	prob float64
	node int
}

type probHeap []probItem // highest probability first

func (h probHeap) Len() int           { return len(h) }
func (h probHeap) Less(i, j int) bool { return h[i].prob > h[j].prob }
func (h probHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *probHeap) Push(x any)        { *h = append(*h, x.(probItem)) }
func (h *probHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

type probEdge struct {
	to   int
	prob float64
}

func maxProbability(n int, edges [][]int, succProb []float64, start int, end int) float64 {
	adj := make([][]probEdge, n)
	for i, e := range edges {
		adj[e[0]] = append(adj[e[0]], probEdge{e[1], succProb[i]})
		adj[e[1]] = append(adj[e[1]], probEdge{e[0], succProb[i]})
	}
	best := make([]float64, n) // best[v] = highest probability found to reach v
	best[start] = 1
	h := &probHeap{{1, start}}
	for h.Len() > 0 {
		cur := heap.Pop(h).(probItem)
		if cur.node == end {
			return cur.prob
		}
		if cur.prob < best[cur.node] {
			continue // stale entry
		}
		for _, e := range adj[cur.node] {
			if cur.prob*e.prob > best[e.to] {
				best[e.to] = cur.prob * e.prob
				heap.Push(h, probItem{best[e.to], e.to})
			}
		}
	}
	return 0
}

