use std::cmp::Ordering;
use std::collections::BinaryHeap;

// f64 has no total order, so wrap it for the heap (probabilities are never NaN)
#[derive(PartialEq)]
struct State {
    prob: f64,
    node: usize,
}
impl Eq for State {}
impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for State {
    fn cmp(&self, other: &Self) -> Ordering {
        self.prob.partial_cmp(&other.prob).unwrap().then_with(|| self.node.cmp(&other.node))
    }
}

impl Solution {
    pub fn max_probability(n: i32, edges: Vec<Vec<i32>>, succ_prob: Vec<f64>, start: i32, end: i32) -> f64 {
        let n = n as usize;
        let (start, end) = (start as usize, end as usize);
        let mut adj: Vec<Vec<(usize, f64)>> = vec![Vec::new(); n];
        for (e, &p) in edges.iter().zip(succ_prob.iter()) {
            adj[e[0] as usize].push((e[1] as usize, p));
            adj[e[1] as usize].push((e[0] as usize, p));
        }
        let mut best = vec![0.0; n]; // best[v] = highest probability found to reach v
        best[start] = 1.0;
        let mut heap = BinaryHeap::new(); // max-heap: highest probability first
        heap.push(State { prob: 1.0, node: start });
        while let Some(State { prob, node: u }) = heap.pop() {
            if u == end {
                return prob;
            }
            if prob < best[u] {
                continue; // stale entry
            }
            for &(v, p) in &adj[u] {
                if prob * p > best[v] {
                    best[v] = prob * p;
                    heap.push(State { prob: best[v], node: v });
                }
            }
        }
        0.0
    }
}

