type swimHeap [][3]int // {time, row, col}, lowest time first

func (h swimHeap) Len() int           { return len(h) }
func (h swimHeap) Less(i, j int) bool { return h[i][0] < h[j][0] }
func (h swimHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *swimHeap) Push(x any)        { *h = append(*h, x.([3]int)) }
func (h *swimHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func swimInWater(grid [][]int) int {
	n := len(grid)
	seen := make([][]bool, n)
	for i := range seen {
		seen[i] = make([]bool, n)
	}
	h := &swimHeap{{grid[0][0], 0, 0}}
	dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	for h.Len() > 0 {
		cur := heap.Pop(h).([3]int)
		t, r, c := cur[0], cur[1], cur[2]
		if seen[r][c] {
			continue
		}
		seen[r][c] = true
		if r == n-1 && c == n-1 {
			return t
		}
		for _, d := range dirs {
			nr, nc := r+d[0], c+d[1]
			if nr < 0 || nc < 0 || nr >= n || nc >= n || seen[nr][nc] {
				continue
			}
			// we must wait until the water covers the next cell too
			heap.Push(h, [3]int{max(t, grid[nr][nc]), nr, nc})
