impl Solution {
    pub fn swim_in_water(grid: Vec<Vec<i32>>) -> i32 {
        let n = grid.len();
        let mut seen = vec![vec![false; n]; n];
        // Reverse makes the max-heap a min-heap: lowest time first
        let mut heap = BinaryHeap::new();
        heap.push(Reverse((grid[0][0], 0usize, 0usize))); // (time we can be here, row, col)
        while let Some(Reverse((t, r, c))) = heap.pop() {
            if seen[r][c] {
                continue;
