            seen[r][c] = true;
            if r == n - 1 && c == n - 1 {
                return t;
            }
            for (dr, dc) in [(1i32, 0i32), (-1, 0), (0, 1), (0, -1)] {
                let (nr, nc) = (r as i32 + dr, c as i32 + dc);
                if nr < 0 || nc < 0 || nr >= n as i32 || nc >= n as i32 {
                    continue;
