                let (nr, nc) = (nr as usize, nc as usize);
                if !seen[nr][nc] {
                    // we must wait until the water covers the next cell too
                    heap.push(Reverse((t.max(grid[nr][nc]), nr, nc)));
                }
            }
        }
        -1
    }
