func minCost(grid [][]int) int {
	m, n := len(grid), len(grid[0])
	dirs := [][2]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}} // arrows 1..4: right, left, down, up
	dist := make([][]int, m)
	for r := range dist {
		dist[r] = make([]int, n)
		for c := range dist[r] {
			dist[r][c] = 1 << 60
		}
	}
	dist[0][0] = 0
	// 0-1 BFS, one cost level at a time (Go has no deque): free moves stay in
	// the current level, moves that change an arrow wait for the next level.
	cur := [][2]int{{0, 0}}
	for level := 0; len(cur) > 0; level++ {
		var next [][2]int
		for len(cur) > 0 {
			p := cur[len(cur)-1]
			cur = cur[:len(cur)-1]
			r, c := p[0], p[1]
			if dist[r][c] != level {
				continue // stale entry: this cell was reached cheaper
			}
			for d, dir := range dirs {
				nr, nc := r+dir[0], c+dir[1]
				if nr < 0 || nc < 0 || nr >= m || nc >= n {
					continue
				}
				w := 1
				if grid[r][c] == d+1 {
					w = 0
				}
				if dist[r][c]+w < dist[nr][nc] {
					dist[nr][nc] = dist[r][c] + w
					if w == 0 {
						cur = append(cur, [2]int{nr, nc})
					} else {
						next = append(next, [2]int{nr, nc})
					}
				}
			}
		}
		cur = next
	}
	return dist[m-1][n-1]
}

