class DSU {
  constructor(n) { this.p = Array.from({ length: n }, (_, i) => i); this.sz = new Array(n).fill(1); this.count = n; }
  find(x) { while (this.p[x] !== x) { this.p[x] = this.p[this.p[x]]; x = this.p[x]; } return x; }
  union(a, b) {
    a = this.find(a); b = this.find(b);
    if (a === b) return false;
    if (this.sz[a] < this.sz[b]) [a, b] = [b, a];
    this.p[b] = a; this.sz[a] += this.sz[b]; this.count--;
    return true;
  }
}
function minimumCost(n, connections) {
    const dsu = new DSU(n + 1);
    const edges = [...connections].sort((a, b) => a[2] - b[2]);
    let total = 0, used = 0;
    for (const [a, b, cost] of edges) {
      if (dsu.union(a, b)) { total += cost; used++; }
    }
    return used === n - 1 ? total : -1;
  }

