			parent[x] = parent[parent[x]] // path halving
			x = parent[x]
		}
		return x
	}
	edges := append([][]int{}, connections...)
	sort.Slice(edges, func(i, j int) bool { return edges[i][2] < edges[j][2] })
	total, used := 0, 0
	// Kruskal: take the cheapest roads first, skip any that close a cycle
	for _, e := range edges {
		ra, rb := find(e[0]), find(e[1])
		if ra != rb {
			parent[ra] = rb
			total += e[2]
			used++
		}
	}
	if used == n-1 {
		return total
	}
	return -1
