import "sort"

func minCostToSupplyWater(n int, wells []int, pipes [][]int) int {
	// Trick: add a virtual node 0 (the water source); a well in house i is an edge 0 - i.
	// The cheapest way to supply every house is then a minimum spanning tree.
	edges := make([][]int, 0, len(pipes)+len(wells))
	edges = append(edges, pipes...)
	for i, cost := range wells {
		edges = append(edges, []int{0, i + 1, cost})
	}
	sort.Slice(edges, func(i, j int) bool { return edges[i][2] < edges[j][2] })

	parent := make([]int, n+1)
	for i := range parent {
		parent[i] = i
	}
	find := func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]] // path halving
			x = parent[x]
		}
		return x
	}
	total := 0
	for _, e := range edges { // Kruskal
		ra, rb := find(e[0]), find(e[1])
		if ra != rb {
			parent[ra] = rb
			total += e[2]
		}
	}
	return total
}

