def find_critical_and_pseudo_critical_edges(n: int, edges: list[list[int]]) -> list[list[int]]:
    order = sorted(range(len(edges)), key=lambda i: edges[i][2])  # edge indexes, cheapest first

    def mst(skip: int, force: int) -> float:
        # Kruskal's cost without edge `skip` and with edge `force` taken first (-1 = none)
        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        cost, parts = 0, n
        if force != -1:
            a, b, w = edges[force]
            parent[find(a)] = find(b)
            cost += w
            parts -= 1
        for i in order:
            if i == skip:
                continue
            a, b, w = edges[i]
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                cost += w
                parts -= 1
        return cost if parts == 1 else float("inf")

    base = mst(-1, -1)
    critical, pseudo = [], []
    for i in range(len(edges)):
        if mst(i, -1) > base:  # without it the tree gets more expensive (or breaks)
            critical.append(i)
        elif mst(-1, i) == base:  # some MST of the best cost uses it
            pseudo.append(i)
    return [critical, pseudo]

