import "sort"

func findCriticalAndPseudoCriticalEdges(n int, edges [][]int) [][]int {
	const inf = 1 << 60
	order := make([]int, len(edges)) // edge indexes, cheapest first
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool { return edges[order[a]][2] < edges[order[b]][2] })

	// Kruskal's cost without edge skip and with edge force taken first (-1 = none)
	mst := func(skip, force int) int {
		parent := make([]int, n)
		for i := range parent {
			parent[i] = i
		}
		find := func(x int) int {
			for parent[x] != x {
				parent[x] = parent[parent[x]]
				x = parent[x]
			}
			return x
		}
		cost, parts := 0, n
		if force != -1 {
			e := edges[force]
			parent[find(e[0])] = find(e[1])
			cost += e[2]
			parts--
		}
		for _, i := range order {
			if i == skip {
				continue
			}
			e := edges[i]
			ra, rb := find(e[0]), find(e[1])
			if ra != rb {
				parent[ra] = rb
				cost += e[2]
				parts--
			}
		}
		if parts == 1 {
			return cost
		}
		return inf
	}

	base := mst(-1, -1)
	critical, pseudo := []int{}, []int{}
	for i := range edges {
		if mst(i, -1) > base { // without it the tree gets more expensive (or breaks)
			critical = append(critical, i)
		} else if mst(-1, i) == base { // some MST of the best cost uses it
			pseudo = append(pseudo, i)
		}
	}
	return [][]int{critical, pseudo}
}

