class Solution {
public:
    vector<vector<int>> findCriticalAndPseudoCriticalEdges(int n, vector<vector<int>>& edges) {
        const int INF = INT_MAX;
        int m = edges.size();
        vector<int> order(m);  // edge indexes, cheapest first
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return edges[a][2] < edges[b][2]; });

        // Kruskal's cost without edge skip and with edge force taken first (-1 = none)
        auto mst = [&](int skip, int force) {
            vector<int> parent(n);
            iota(parent.begin(), parent.end(), 0);
            auto find = [&](int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            };
            int cost = 0, parts = n;
            if (force != -1) {
                parent[find(edges[force][0])] = find(edges[force][1]);
                cost += edges[force][2];
                parts--;
            }
            for (int i : order) {
                if (i == skip) continue;
                int ra = find(edges[i][0]), rb = find(edges[i][1]);
                if (ra != rb) {
                    parent[ra] = rb;
                    cost += edges[i][2];
                    parts--;
                }
            }
            return parts == 1 ? cost : INF;
        };

        int base = mst(-1, -1);
        vector<int> critical, pseudo;
        for (int i = 0; i < m; i++) {
            if (mst(i, -1) > base) critical.push_back(i);        // without it the tree gets more expensive (or breaks)
            else if (mst(-1, i) == base) pseudo.push_back(i);    // some MST of the best cost uses it
        }
        return {critical, pseudo};
    }
};

