    pub fn find_critical_and_pseudo_critical_edges(n: i32, edges: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
        let n = n as usize;
        let mut order: Vec<usize> = (0..edges.len()).collect(); // edge indexes, cheapest first
        order.sort_by_key(|&i| edges[i][2]);

        fn find(parent: &mut Vec<usize>, mut x: usize) -> usize {
            while parent[x] != x {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            x
        }

        // Kruskal's cost without edge `skip` and with edge `force` taken first (None = no such edge)
        let mst = |skip: Option<usize>, force: Option<usize>| -> i32 {
            let mut parent: Vec<usize> = (0..n).collect();
            let (mut cost, mut parts) = (0, n);
            if let Some(f) = force {
                let (a, b) = (find(&mut parent, edges[f][0] as usize), find(&mut parent, edges[f][1] as usize));
                parent[a] = b;
                cost += edges[f][2];
                parts -= 1;
            }
            for &i in &order {
                if Some(i) == skip {
                    continue;
                }
                let (ra, rb) = (find(&mut parent, edges[i][0] as usize), find(&mut parent, edges[i][1] as usize));
                if ra != rb {
                    parent[ra] = rb;
                    cost += edges[i][2];
                    parts -= 1;
                }
            }
            if parts == 1 { cost } else { i32::MAX }
        };

        let base = mst(None, None);
        let (mut critical, mut pseudo) = (Vec::new(), Vec::new());
        for i in 0..edges.len() {
            if mst(Some(i), None) > base {
                critical.push(i as i32); // without it the tree gets more expensive (or breaks)
            } else if mst(None, Some(i)) == base {
                pseudo.push(i as i32); // some MST of the best cost uses it
            }
        }
        vec![critical, pseudo]
    }
}

