def accounts_merge(accounts: list[list[str]]) -> list[list[str]]:
    parent = list(range(len(accounts)))  # union-find over account indexes

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving keeps the trees flat
            x = parent[x]
        return x

    owner = {}  # email -> the first account that listed it
    for i, acc in enumerate(accounts):
        for email in acc[1:]:
            if email in owner:  # a shared email means the same person
                a, b = find(i), find(owner[email])
                parent[a] = b
            else:
                owner[email] = i
    groups = {}  # root account -> all emails of that person
    for email, i in owner.items():
        groups.setdefault(find(i), []).append(email)
    merged = [[accounts[root][0]] + sorted(emails) for root, emails in groups.items()]
    return sorted(merged, key=lambda acc: acc[1])  # order by the smallest email

