	groups := map[int][]string{} // root account -> all emails of that person
	for email, i := range owner {
		root := find(i)
		groups[root] = append(groups[root], email)
	}
	merged := [][]string{}
	for root, emails := range groups {
		sort.Strings(emails)
		merged = append(merged, append([]string{accounts[root][0]}, emails...))
	}
	sort.Slice(merged, func(i, j int) bool { return merged[i][1] < merged[j][1] }) // order by the smallest email
