class Solution {
public:
    vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {
        int n = accounts.size();
        vector<int> parent(n);  // union-find over account indexes
        iota(parent.begin(), parent.end(), 0);
        auto find = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];  // path halving keeps the trees flat
                x = parent[x];
            }
            return x;
        };
        unordered_map<string, int> owner;  // email -> the first account that listed it
        for (int i = 0; i < n; i++)
            for (size_t k = 1; k < accounts[i].size(); k++) {
                auto it = owner.find(accounts[i][k]);
                if (it != owner.end()) {  // a shared email means the same person
                    int a = find(i), b = find(it->second);
                    parent[a] = b;
                } else {
                    owner[accounts[i][k]] = i;
                }
            }
        map<int, vector<string>> groups;  // root account -> all emails of that person
        for (auto& [email, i] : owner) groups[find(i)].push_back(email);
        vector<vector<string>> merged;
        for (auto& [root, emails] : groups) {
            sort(emails.begin(), emails.end());
            vector<string> row = {accounts[root][0]};
            row.insert(row.end(), emails.begin(), emails.end());
            merged.push_back(row);
        }
        sort(merged.begin(), merged.end(), [](auto& a, auto& b) { return a[1] < b[1]; });  // order by the smallest email
        return merged;
    }
};

