object Solution {
  def accountsMerge(accounts: Array[Array[String]]): Array[Array[String]] = {
    val parent = Array.tabulate(accounts.length)(i => i) // union-find over account indexes
    def find(start: Int): Int = {
      var x = start
      while (parent(x) != x) {
        parent(x) = parent(parent(x)) // path halving keeps the trees flat
        x = parent(x)
      }
      x
    }
    val owner = scala.collection.mutable.HashMap[String, Int]() // email -> the first account that listed it
    for (i <- accounts.indices; k <- 1 until accounts(i).length) {
      val email = accounts(i)(k)
      if (owner.contains(email)) { // a shared email means the same person
        val a = find(i)
        val b = find(owner(email))
        parent(a) = b
      } else {
        owner(email) = i
      }
    }
    val groups = scala.collection.mutable.HashMap[Int, scala.collection.mutable.ArrayBuffer[String]]() // root account -> all emails
    for ((email, i) <- owner) {
      groups.getOrElseUpdate(find(i), scala.collection.mutable.ArrayBuffer[String]()) += email
    }
    val merged = groups.toArray.map { case (root, emails) =>
      (accounts(root)(0) +: emails.sorted).toArray
    }
    merged.sortBy(row => row(1)) // order by the smallest email
  }
}

