class Solution {
public:
    int removeStones(vector<vector<int>>& stones) {
        // Every stone joins its row and its column. In each connected group of
        // stones we can remove all but one, so the answer is stones - groups.
        const int OFFSET = 10001;  // keeps column keys apart from row keys
        unordered_map<int, int> ids;  // row / column key -> union-find node
        auto node = [&](int key) {
            auto it = ids.find(key);
            if (it != ids.end()) return it->second;
            int id = ids.size();
            ids[key] = id;
            return id;
        };
        vector<pair<int, int>> pairs;
        for (auto& s : stones) {
            int a = node(s[0]);
            int b = node(s[1] + OFFSET);
            pairs.push_back({a, b});
        }
        vector<int> parent(ids.size());
        iota(parent.begin(), parent.end(), 0);
        auto find = [&](int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];  // path halving keeps the trees flat
                x = parent[x];
            }
            return x;
        };
        int groups = ids.size();
        for (auto& [a, b] : pairs) {
            int ra = find(a), rb = find(b);
            if (ra != rb) {
                parent[ra] = rb;
                groups--;
            }
        }
        return (int)stones.size() - groups;
    }
};

