def replace_words(dictionary: list[str], sentence: str) -> str:
    # Trie of the roots: a node maps a letter to its child; the key "$" marks the end of a root.
    root = {}
    for r in dictionary:
        node = root
        for ch in r:
            node = node.setdefault(ch, {})
        node["$"] = True

    def shorten(word: str) -> str:
        node = root
        for i, ch in enumerate(word):
            if ch not in node:
                return word  # fell off the trie: no root is a prefix
            node = node[ch]
            if "$" in node:
                return word[:i + 1]  # the first root we meet is the shortest one
        return word

    return " ".join(shorten(w) for w in sentence.split(" "))

