class MapSum {
    // Nodes live in vectors; node 0 is the root, and 0 in next[] means "no child".
    vector<array<int, 26>> next;
    vector<int> total;                // total value of the keys passing through each node
    unordered_map<string, int> values;  // key -> its current value

