        next.push_back({});  // all zeros
        total.push_back(0);
        return (int)next.size() - 1;
    }

public:
    MapSum() {
        newNode();
    }

    void insert(string key, int value) {
        int delta = value - values[key];  // a new value replaces the old one (0 if the key is new)
        values[key] = value;
        int node = 0;
        for (char ch : key) {
            if (next[node][ch - 'a'] == 0) {
                int child = newNode();
                next[node][ch - 'a'] = child;
            }
            node = next[node][ch - 'a'];
            total[node] += delta;
        }
    }

    int sum(string prefix) {
        int node = 0;
        for (char ch : prefix) {
            node = next[node][ch - 'a'];
            if (node == 0) return 0;
        }
        return total[node];
    }
};

