def find_maximum_xor(nums: list[int]) -> int:
    BITS = 30  # every number is below 2^31
    # trie[node] = [child for bit 0, child for bit 1]; 0 means "no child" (node 0 is the root)
    trie = [[0, 0]]
    for x in nums:
        node = 0
        for b in range(BITS, -1, -1):
            bit = (x >> b) & 1
            if not trie[node][bit]:
                trie.append([0, 0])
                trie[node][bit] = len(trie) - 1
            node = trie[node][bit]

    best = 0
    for x in nums:
        node = 0
        cur = 0
        for b in range(BITS, -1, -1):
            want = ((x >> b) & 1) ^ 1  # the opposite bit puts a 1 in the XOR
            if trie[node][want]:
                cur |= 1 << b
                node = trie[node][want]
            else:
                node = trie[node][want ^ 1]
        best = max(best, cur)
    return best

