object Solution {
  def findMaximumXor(nums: Array[Int]): Int = {
    val BITS = 30 // every number is below 2^31
    // trie(node)(bit) is the child index; 0 means "no child" (node 0 is the root)
    val trie = ArrayBuffer(Array(0, 0))
    for (x <- nums) {
      var node = 0
      var b = BITS
      while (b >= 0) {
        val bit = (x >> b) & 1
        if (trie(node)(bit) == 0) {
          trie += Array(0, 0)
          trie(node)(bit) = trie.length - 1
        }
        node = trie(node)(bit)
        b -= 1
      }
    }

    var best = 0
    for (x <- nums) {
      var node = 0
      var cur = 0
      var b = BITS
      while (b >= 0) {
        val want = ((x >> b) & 1) ^ 1 // the opposite bit puts a 1 in the XOR
        if (trie(node)(want) != 0) {
          cur |= 1 << b
          node = trie(node)(want)
        } else {
          node = trie(node)(want ^ 1)
        }
        b -= 1
      }
      best = math.max(best, cur)
    }
    best
  }
}

