import "container/heap"

type letterCount struct{ count, letter int }

// letterHeap puts the letter with most copies on top; on a tie the smaller letter.
type letterHeap []letterCount

func (h letterHeap) Len() int { return len(h) }
func (h letterHeap) Less(i, j int) bool {
	if h[i].count != h[j].count {
		return h[i].count > h[j].count
	}
	return h[i].letter < h[j].letter
}
func (h letterHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *letterHeap) Push(x any)   { *h = append(*h, x.(letterCount)) }
func (h *letterHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func reorganizeString(s string) string {
	var cnt [26]int
	for i := 0; i < len(s); i++ {
		cnt[s[i]-'a']++
	}
	h := &letterHeap{}
	for letter, c := range cnt {
		if c > 0 {
			heap.Push(h, letterCount{c, letter})
		}
	}
	out := []byte{}
	var held letterCount // the letter just used: it may not go next, so it waits one step
	hasHeld := false
	for h.Len() > 0 {
		top := heap.Pop(h).(letterCount)
		out = append(out, byte('a'+top.letter))
		if hasHeld {
			heap.Push(h, held)
		}
		hasHeld = top.count > 1 // copies left after this one?
		held = letterCount{top.count - 1, top.letter}
	}
	if hasHeld {
		return "" // a letter still waiting means no valid order
	}
	return string(out)
}

