        let mut heap = BinaryHeap::new();
        for (i, &c) in cnt.iter().enumerate() {
            if c > 0 {
                heap.push((c, -(i as i32)));
            }
        }
        let mut out = String::new();
        let mut held: Option<(i32, i32)> = None; // the letter just used: it waits one step
        while let Some((count, neg_letter)) = heap.pop() {
            out.push((b'a' as i32 - neg_letter) as u8 as char);
            if let Some(h) = held {
                heap.push(h);
            }
            // copies left after this one?
            held = if count > 1 { Some((count - 1, neg_letter)) } else { None };
        }
        if held.is_some() {
            return String::new(); // a letter still waiting means no valid order
        }
        out
    }
}

