import heapq

def find_maximized_capital(k: int, w: int, profits: list[int], capital: list[int]) -> int:
    order = sorted(range(len(profits)), key=lambda i: capital[i])  # projects by capital needed
    available = []  # max-heap (negated) of profits of projects we can afford now
    nxt = 0
    for _ in range(k):
        while nxt < len(order) and capital[order[nxt]] <= w:
            heapq.heappush(available, -profits[order[nxt]])
            nxt += 1
        if not available:
            break  # nothing affordable
        w += -heapq.heappop(available)  # do the most profitable affordable project
    return w

