class Solution {
public:
    int findMaximizedCapital(int k, int w, vector<int>& profits, vector<int>& capital) {
        int n = profits.size();
        vector<int> order(n);  // project indices, cheapest capital first
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return capital[a] < capital[b]; });

        priority_queue<int> available;  // max-heap: profits of projects we can afford now
        int next = 0;
        for (int round = 0; round < k; round++) {
            while (next < n && capital[order[next]] <= w) {
                available.push(profits[order[next]]);
                next++;
            }
            if (available.empty()) break;  // nothing affordable
            w += available.top();          // do the most profitable affordable project
            available.pop();
        }
        return w;
    }
};

