import "container/heap"

// rangeItem points at one element of one list.
type rangeItem struct{ val, list, pos int }

// rangeMinHeap is a min-heap ordered by val.
type rangeMinHeap []rangeItem

func (h rangeMinHeap) Len() int           { return len(h) }
func (h rangeMinHeap) Less(i, j int) bool { return h[i].val < h[j].val }
func (h rangeMinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *rangeMinHeap) Push(x any)        { *h = append(*h, x.(rangeItem)) }
func (h *rangeMinHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func smallestRange(nums [][]int) []int {
	// min-heap with one element from every list
	h := &rangeMinHeap{}
	hi := nums[0][0] // largest value currently in the heap
	for i, lst := range nums {
		heap.Push(h, rangeItem{lst[0], i, 0})
		if lst[0] > hi {
			hi = lst[0]
		}
	}
	best := []int{(*h)[0].val, hi}
	for {
		it := heap.Pop(h).(rangeItem)
		if hi-it.val < best[1]-best[0] {
			best = []int{it.val, hi}
		}
		if it.pos+1 == len(nums[it.list]) {
			break // a list ran out: no range can cover all lists any more
		}
		nv := nums[it.list][it.pos+1]
		heap.Push(h, rangeItem{nv, it.list, it.pos + 1})
