public:
    vector<int> smallestRange(vector<vector<int>>& nums) {
        // min-heap with one element from every list: {value, which list, position}
        using Item = array<int, 3>;
        priority_queue<Item, vector<Item>, greater<Item>> heap;
        int hi = nums[0][0];  // largest value currently in the heap
        for (int i = 0; i < (int)nums.size(); i++) {
            heap.push({nums[i][0], i, 0});
            hi = max(hi, nums[i][0]);
        }
        vector<int> best = {heap.top()[0], hi};
        while (true) {
            auto [val, i, j] = heap.top();
            heap.pop();
            if (hi - val < best[1] - best[0]) best = {val, hi};
            if (j + 1 == (int)nums[i].size()) break;  // a list ran out: no range can cover all lists
            int nv = nums[i][j + 1];
            heap.push({nv, i, j + 1});
            hi = max(hi, nv);
            int lo = heap.top()[0];
            if (hi - lo < best[1] - best[0]) best = {lo, hi};
        }
        return best;
    }
};

