func findTargetSumWays(nums []int, target int) int {
	// P = numbers with +, N = numbers with -: P - N = target and P + N = total,
	// so P = (total + target) / 2. Count the subsets of nums that sum to P.
	total := 0
	for _, x := range nums {
		total += x
	}
	abs := target
	if abs < 0 {
		abs = -abs
	}
	if abs > total || (total+target)%2 != 0 {
		return 0
	}
	need := (total + target) / 2
	ways := make([]int, need+1) // ways[s] = number of subsets with sum s
	ways[0] = 1
	for _, num := range nums {
		for s := need; s >= num; s-- { // downwards: each number is used once
			ways[s] += ways[s-num]
		}
	}
	return ways[need]
}

