def num_squares(n: int) -> int:
    dp = [0] * (n + 1)  # dp[i] = fewest squares that sum to i
    for i in range(1, n + 1):
        dp[i] = i  # worst case: i copies of 1
        j = 1
        while j * j <= i:
            dp[i] = min(dp[i], dp[i - j * j] + 1)  # use one square j*j
            j += 1
    return dp[n]

