func lastStoneWeightIi(stones []int) int {
	// Smashing stones = giving each stone a + or - sign. The smallest |sum| comes from
	// splitting the stones into two piles whose weights are as close as possible.
	total := 0
	for _, w := range stones {
		total += w
	}
	half := total / 2
	can := make([]bool, half+1) // can[s] = some subset of the stones weighs exactly s
	can[0] = true
	for _, w := range stones {
		for s := half; s >= w; s-- { // downwards: each stone is used once
			if can[s-w] {
				can[s] = true
			}
		}
	}
	for s := half; s >= 0; s-- { // the heaviest pile that fits in half the total
		if can[s] {
			return total - 2*s
		}
	}
	return total
}

