def find_max_form(strs: list[str], m: int, n: int) -> int:
    # 0/1 knapsack with two capacities: m zeros and n ones
    dp = [[0] * (n + 1) for _ in range(m + 1)]  # dp[i][j] = most strings using at most i zeros and j ones
    for s in strs:
        zeros = s.count("0")
        ones = len(s) - zeros
        for i in range(m, zeros - 1, -1):  # downwards: each string is used once
            for j in range(n, ones - 1, -1):
                dp[i][j] = max(dp[i][j], dp[i - zeros][j - ones] + 1)
    return dp[m][n]

