	for _, s := range strs {
		zeros := 0
		for _, ch := range s {
			if ch == '0' {
				zeros++
			}
		}
		ones := len(s) - zeros
		for i := m; i >= zeros; i-- { // downwards: each string is used once
			for j := n; j >= ones; j-- {
				if v := dp[i-zeros][j-ones] + 1; v > dp[i][j] {
					dp[i][j] = v
				}
			}
		}
	}
