def longest_palindrome_subseq(s: str) -> int:
    n = len(s)
    nxt = [0] * n  # nxt[j] = longest palindromic subsequence of s[i+1..j]
    for i in range(n - 1, -1, -1):
        cur = [0] * n  # cur[j] = longest palindromic subsequence of s[i..j]
        cur[i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                cur[j] = nxt[j - 1] + 2  # both ends match: wrap them around the inside
            else:
                cur[j] = max(nxt[j], cur[j - 1])  # drop the left end or the right end
        nxt = cur
    return nxt[n - 1] if n else 0

