      } else if (left == HasCamera || right == HasCamera) {
        Watched // a child's camera watches this node
      } else {
        NotWatched // nothing below watches us: let the parent place a camera
      }
    }

    if (state(root) == NotWatched) cameras += 1 // the root itself is unwatched
    cameras
  }
}

