func longestStrChain(words []string) int {
	sorted := append([]string(nil), words...)
	// shorter words first, so every predecessor is already known
	sort.Slice(sorted, func(a, b int) bool { return len(sorted[a]) < len(sorted[b]) })
	chain := make(map[string]int) // chain[w] = longest chain that ends with w
	best := 0
	for _, w := range sorted {
		cur := 1
		for i := 0; i < len(w); i++ {
			prev := w[:i] + w[i+1:] // w with one letter removed
			cur = max(cur, chain[prev]+1)
		}
		chain[w] = cur
		best = max(best, cur)
