func largestDivisibleSubset(nums []int) []int {
	a := append([]int(nil), nums...)
	sort.Ints(a)
	n := len(a)
	size := make([]int, n) // size[i] = largest divisible chain that ends with a[i]
	prev := make([]int, n) // prev[i] = the element before a[i] in that chain
	end := 0
	for i := 0; i < n; i++ {
		size[i], prev[i] = 1, -1
		for j := 0; j < i; j++ {
			// in sorted order, a[j] | a[i] is enough: divisibility is transitive along the chain
			if a[i]%a[j] == 0 && size[j]+1 > size[i] {
				size[i] = size[j] + 1
				prev[i] = j
			}
		}
		if size[i] > size[end] {
			end = i
		}
	}
	var out []int
	for i := end; i != -1; i = prev[i] {
		out = append(out, a[i])
	}
	for l, r := 0, len(out)-1; l < r; l, r = l+1, r-1 {
		out[l], out[r] = out[r], out[l]
	}
	return out
