func shortestPathLength(n int, edges [][]int) int {
	if n == 1 {
		return 0
	}
	adj := make([][]int, n)
	for _, e := range edges {
		adj[e[0]] = append(adj[e[0]], e[1])
		adj[e[1]] = append(adj[e[1]], e[0])
	}
	full := (1 << n) - 1 // bit v of the mask = node v has been visited
	// BFS over states (node, set of visited nodes), starting from every node at once
	seen := make([][]bool, n)
	var queue [][2]int
	for i := 0; i < n; i++ {
		seen[i] = make([]bool, 1<<n)
		seen[i][1<<i] = true
		queue = append(queue, [2]int{i, 1 << i})
	}
	for dist := 0; len(queue) > 0; dist++ {
		var next [][2]int
		for _, state := range queue {
			node, mask := state[0], state[1]
			if mask == full {
				return dist
			}
			for _, v := range adj[node] {
				mask2 := mask | 1<<v
				if !seen[v][mask2] {
					seen[v][mask2] = true
					next = append(next, [2]int{v, mask2})
				}
			}
		}
		queue = next
	}
	return -1
}

