def can_partition_k_subsets(nums: list[int], k: int) -> bool:
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    n = len(nums)
    if max(nums) > target:
        return False
    # fill[mask] = sum of the numbers in mask, modulo target (how full the current subset is);
    # -1 means this set of numbers cannot be packed into whole subsets
    fill = [-1] * (1 << n)
    fill[0] = 0
    for mask in range(1 << n):
        if fill[mask] == -1:
            continue
        for i in range(n):
            if mask & (1 << i):
                continue
            nxt = mask | (1 << i)
            if fill[nxt] == -1 and fill[mask] + nums[i] <= target:
                fill[nxt] = (fill[mask] + nums[i]) % target
    return fill[(1 << n) - 1] == 0

