def smallest_sufficient_team(req_skills: list[str], people: list[list[str]]) -> list[int]:
    bit = {skill: i for i, skill in enumerate(req_skills)}
    masks = []  # masks[p] = the skills of person p, one bit per skill
    for skills in people:
        m = 0
        for s in skills:
            m |= 1 << bit[s]
        masks.append(m)

    team = {0: []}  # skill set -> smallest team found for exactly that set
    for p, m in enumerate(masks):
        if m == 0:
            continue
        for mask, members in list(team.items()):  # a snapshot: person p is used at most once
            nxt = mask | m
            if nxt != mask and (nxt not in team or len(team[nxt]) > len(members) + 1):
                team[nxt] = members + [p]
    return team[(1 << len(req_skills)) - 1]

