impl Solution {
    pub fn smallest_sufficient_team(req_skills: Vec<String>, people: Vec<Vec<String>>) -> Vec<i32> {
        let bit: HashMap<&str, usize> = req_skills.iter().enumerate().map(|(i, s)| (s.as_str(), i)).collect();
        let full = (1usize << req_skills.len()) - 1;
        let mut team: Vec<Option<Vec<i32>>> = vec![None; full + 1]; // team[mask] = smallest team for exactly that skill set
        team[0] = Some(vec![]);
        for (p, skills) in people.iter().enumerate() {
            let m = skills.iter().fold(0usize, |acc, s| acc | (1 << bit[s.as_str()])); // one bit per skill
            if m == 0 {
                continue;
            }
            for mask in 0..=full {
                let len = match &team[mask] {
                    Some(t) => t.len(),
                    None => continue,
                };
                let next = mask | m;
                if next == mask {
                    continue;
                }
                let better = match &team[next] {
                    None => true,
                    Some(t) => t.len() > len + 1,
                };
                if better {
                    let mut t = team[mask].clone().unwrap();
                    t.push(p as i32);
                    team[next] = Some(t);
                }
            }
        }
        team[full].clone().unwrap()
    }
}

