        for (mask <- 0 to full if reached(mask)) {
          val next = mask | m
          if (next != mask && (!reached(next) || team(next).length > team(mask).length + 1)) {
            team(next) = team(mask) :+ p
            reached(next) = true
          }
        }
      }
    }
    team(full).toArray
  }
}

