struct NumArray {
    nums: Vec<i32>,
    tree: Vec<i32>, // Fenwick tree, positions 1..n
}

impl NumArray {
    fn new(nums: Vec<i32>) -> Self {
        let mut a = NumArray { nums: vec![0; nums.len()], tree: vec![0; nums.len() + 1] };
        for (i, &v) in nums.iter().enumerate() {
            a.set(i, v);
        }
        a
    }

    // Change position i to v, keeping the tree in step.
    fn set(&mut self, i: usize, v: i32) {
        let delta = v - self.nums[i];
        self.nums[i] = v;
        let mut j = i + 1;
        while j < self.tree.len() {
            self.tree[j] += delta;
            j += j & j.wrapping_neg(); // next block that contains j
        }
    }

    // Sum of the first count numbers.
    fn prefix(&self, count: usize) -> i32 {
        let (mut total, mut j) = (0, count);
        while j > 0 {
            total += self.tree[j];
            j &= j - 1; // drop the lowest set bit
        }
        total
    }

    fn update(&mut self, index: i32, value: i32) {
        self.set(index as usize, value);
    }

    fn sum_range(&self, left: i32, right: i32) -> i32 {
        self.prefix(right as usize + 1) - self.prefix(left as usize)
    }
}

