class NumArray(_nums: Array[Int]) {
  private val n = _nums.length
  private val nums = new Array[Int](n)
  private val tree = new Array[Int](n + 1) // Fenwick tree, positions 1..n
  for (i <- 0 until n) update(i, _nums(i))

