    val delta = value - nums(index)
    nums(index) = value
    var j = index + 1
    while (j <= n) {
      tree(j) += delta
      j += j & -j // next block that contains j
    }
  }

  // sum of the first count numbers
  private def prefix(count: Int): Int = {
    var total = 0
    var j = count
    while (j > 0) {
      total += tree(j)
      j -= j & -j // drop the lowest set bit
    }
    total
  }

  def sumRange(left: Int, right: Int): Int = prefix(right + 1) - prefix(left)
}

