import "sort"

func countSmaller(nums []int) []int {
	// replace each value by its rank among the sorted distinct values (1..m)
	sorted := append([]int{}, nums...)
	sort.Ints(sorted)
	distinct := sorted[:0]
	for i, v := range sorted {
		if i == 0 || v != sorted[i-1] {
			distinct = append(distinct, v)
		}
	}
	m := len(distinct)
	tree := make([]int, m+1) // Fenwick tree: how many of the numbers seen so far have each rank
	counts := make([]int, len(nums))
	for i := len(nums) - 1; i >= 0; i-- {
		r := sort.SearchInts(distinct, nums[i]) + 1
		for j := r - 1; j > 0; j -= j & -j { // count the seen numbers with a smaller rank
			counts[i] += tree[j]
		}
		for j := r; j <= m; j += j & -j { // then add nums[i] itself
			tree[j]++
		}
	}
	return counts
}

