def count_range_sum(nums: list[int], lower: int, upper: int) -> int:
    prefix = [0]  # prefix[k] = sum of the first k numbers
    for x in nums:
        prefix.append(prefix[-1] + x)

    def sort_count(lo: int, hi: int) -> int:
        # sorts prefix[lo:hi] and counts pairs i < j inside it with lower <= prefix[j] - prefix[i] <= upper
        if hi - lo <= 1:
            return 0
        mid = (lo + hi) // 2
        count = sort_count(lo, mid) + sort_count(mid, hi)
        # both halves are sorted: for each left value the matching right values form a window that only moves forward
        a = b = mid
        for i in range(lo, mid):
            while a < hi and prefix[a] - prefix[i] < lower:
                a += 1
            while b < hi and prefix[b] - prefix[i] <= upper:
                b += 1
            count += b - a
        prefix[lo:hi] = sorted(prefix[lo:hi])  # merge the two sorted halves (Timsort merges sorted runs in linear time)
        return count

    return sort_count(0, len(prefix))

