fn sort_count(prefix: &mut Vec<i64>, lo: usize, hi: usize, lower: i64, upper: i64) -> i64 {
    if hi - lo <= 1 {
        return 0;
    }
    let mid = (lo + hi) / 2;
    let mut count = sort_count(prefix, lo, mid, lower, upper) + sort_count(prefix, mid, hi, lower, upper);
    // both halves are sorted: for each left value the matching right values form a window that only moves forward
    let (mut a, mut b) = (mid, mid);
    for i in lo..mid {
        while a < hi && prefix[a] - prefix[i] < lower {
            a += 1;
        }
        while b < hi && prefix[b] - prefix[i] <= upper {
            b += 1;
        }
        count += (b - a) as i64;
    }
    // merge the two sorted halves
    let mut merged = Vec::with_capacity(hi - lo);
    let (mut p, mut q) = (lo, mid);
    while p < mid || q < hi {
        if q >= hi || (p < mid && prefix[p] <= prefix[q]) {
            merged.push(prefix[p]);
            p += 1;
        } else {
            merged.push(prefix[q]);
            q += 1;
        }
    }
    prefix[lo..hi].copy_from_slice(&merged);
    count
}

