object Solution {
  def countRangeSum(nums: Array[Int], lower: Int, upper: Int): Int = {
    val prefix = new Array[Long](nums.length + 1) // prefix(k) = sum of the first k numbers
    for (i <- nums.indices) prefix(i + 1) = prefix(i) + nums(i)

    // sorts prefix[lo, hi) and counts pairs i < j inside it with lower <= prefix(j) - prefix(i) <= upper
    def sortCount(lo: Int, hi: Int): Int = {
      if (hi - lo <= 1) {
        0
      } else {
        val mid = (lo + hi) / 2
        var count = sortCount(lo, mid) + sortCount(mid, hi)
        // both halves are sorted: for each left value the matching right values form a window that only moves forward
        var a = mid
        var b = mid
        for (i <- lo until mid) {
          while (a < hi && prefix(a) - prefix(i) < lower) a += 1
          while (b < hi && prefix(b) - prefix(i) <= upper) b += 1
          count += b - a
        }
        // merge the two sorted halves
        val merged = new Array[Long](hi - lo)
        var p = lo
        var q = mid
        var k = 0
        while (p < mid || q < hi) {
          if (q >= hi || (p < mid && prefix(p) <= prefix(q))) {
            merged(k) = prefix(p)
            p += 1
          } else {
            merged(k) = prefix(q)
            q += 1
          }
          k += 1
        }
        System.arraycopy(merged, 0, prefix, lo, merged.length)
        count
      }
    }

    sortCount(0, prefix.length)
  }
}

