import "sort"

func fallingSquares(positions [][]int) []int {
	// only the edges matter: compress them, so the cells between neighbouring edges have one height each
	var xs []int
	for _, p := range positions {
		xs = append(xs, p[0], p[0]+p[1])
	}
	sort.Ints(xs)
	n := 0
	for i, x := range xs {
		if i == 0 || x != xs[i-1] {
			xs[n] = x
			n++
		}
	}
	xs = xs[:n]

	height := make([]int, n) // height[c] = stack height over the cell starting at xs[c]
	answer := make([]int, 0, len(positions))
	top := 0
	for _, p := range positions {
		a := sort.SearchInts(xs, p[0])
		b := sort.SearchInts(xs, p[0]+p[1])
		level := 0 // the square lands on the tallest cell under it
		for c := a; c < b; c++ {
			if height[c] > level {
				level = height[c]
			}
		}
		for c := a; c < b; c++ {
			height[c] = level + p[1]
		}
		if level+p[1] > top {
			top = level + p[1]
		}
		answer = append(answer, top)
	}
	return answer
}

