class Solution {
public:
    vector<int> fallingSquares(vector<vector<int>>& positions) {
        // only the edges matter: compress them, so the cells between neighbouring edges have one height each
        vector<int> xs;
        for (auto& p : positions) {
            xs.push_back(p[0]);
            xs.push_back(p[0] + p[1]);
        }
        sort(xs.begin(), xs.end());
        xs.erase(unique(xs.begin(), xs.end()), xs.end());
        auto cell = [&](int x) { return int(lower_bound(xs.begin(), xs.end(), x) - xs.begin()); };

        vector<int> height(xs.size(), 0);  // height[c] = stack height over the cell starting at xs[c]
        vector<int> answer;
        int top = 0;
        for (auto& p : positions) {
            int a = cell(p[0]), b = cell(p[0] + p[1]);
            int level = 0;  // the square lands on the tallest cell under it
            for (int c = a; c < b; c++) level = max(level, height[c]);
            for (int c = a; c < b; c++) height[c] = level + p[1];
            top = max(top, level + p[1]);
            answer.push_back(top);
        }
        return answer;
    }
};

