impl Solution {
    pub fn falling_squares(positions: Vec<Vec<i32>>) -> Vec<i32> {
        // only the edges matter: compress them, so the cells between neighbouring edges have one height each
        let mut xs: Vec<i32> = positions.iter().flat_map(|p| [p[0], p[0] + p[1]]).collect();
        xs.sort_unstable();
        xs.dedup();

        let mut height = vec![0; xs.len()]; // height[c] = stack height over the cell starting at xs[c]
        let mut answer = Vec::with_capacity(positions.len());
        let mut top = 0;
        for p in &positions {
            let a = xs.binary_search(&p[0]).unwrap();
            let b = xs.binary_search(&(p[0] + p[1])).unwrap();
            let level = height[a..b].iter().copied().max().unwrap_or(0); // lands on the tallest cell under it
            for h in &mut height[a..b] {
                *h = level + p[1];
            }
            top = top.max(level + p[1]);
            answer.push(top);
        }
        answer
    }
}

