import "math"

func findMedianSortedArrays(nums1 []int, nums2 []int) float64 {
	a, b := nums1, nums2 // binary search on the shorter one
	if len(a) > len(b) {
		a, b = b, a
	}
	m, n := len(a), len(b)
	half := (m + n + 1) / 2 // size of the combined left side
	lo, hi := 0, m
	for lo <= hi {
		i := (lo + hi) / 2 // i elements of a go to the left side ...
		j := half - i      // ... and j elements of b
		aLeft, aRight, bLeft, bRight := math.MinInt, math.MaxInt, math.MinInt, math.MaxInt
		if i > 0 {
			aLeft = a[i-1]
		}
		if i < m {
			aRight = a[i]
		}
		if j > 0 {
			bLeft = b[j-1]
		}
		if j < n {
			bRight = b[j]
		}
		if aLeft <= bRight && bLeft <= aRight { // a correct cut
			if (m+n)%2 == 1 {
				return float64(max(aLeft, bLeft))
			}
			return float64(max(aLeft, bLeft)+min(aRight, bRight)) / 2
		}
		if aLeft > bRight {
			hi = i - 1 // took too many from a
		} else {
			lo = i + 1
		}
	}
	return 0
}

