    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        // binary search on the shorter one
        const vector<int>& a = nums1.size() <= nums2.size() ? nums1 : nums2;
        const vector<int>& b = nums1.size() <= nums2.size() ? nums2 : nums1;
        int m = a.size(), n = b.size();
        int half = (m + n + 1) / 2;  // size of the combined left side
        int lo = 0, hi = m;
        while (lo <= hi) {
            int i = (lo + hi) / 2;  // i elements of a go to the left side ...
            int j = half - i;       // ... and j elements of b
            int aLeft = i > 0 ? a[i - 1] : INT_MIN;
            int aRight = i < m ? a[i] : INT_MAX;
            int bLeft = j > 0 ? b[j - 1] : INT_MIN;
            int bRight = j < n ? b[j] : INT_MAX;
            if (aLeft <= bRight && bLeft <= aRight) {  // a correct cut
                if ((m + n) % 2 == 1) return max(aLeft, bLeft);
                return ((double)max(aLeft, bLeft) + min(aRight, bRight)) / 2.0;
            }
            if (aLeft > bRight) hi = i - 1;  // took too many from a
            else lo = i + 1;
        }
        return 0;
    }
};

