// Sorts a[lo..hi] and counts pairs i < j inside it with a[i] > 2 * a[j].
fn sort_count(a: &mut Vec<i64>, lo: usize, hi: usize) -> i64 {
    if hi - lo <= 1 {
        return 0;
    }
    let mid = (lo + hi) / 2;
    let mut count = sort_count(a, lo, mid) + sort_count(a, mid, hi);
    let mut p = mid; // right values a[mid..p] are small enough for the current left value; p only moves forward
    for i in lo..mid {
        while p < hi && a[i] > 2 * a[p] {
            p += 1;
        }
        count += (p - mid) as i64;
    }
    // merge the two sorted halves
    let mut merged = Vec::with_capacity(hi - lo);
    let (mut l, mut r) = (lo, mid);
    while l < mid || r < hi {
        if r >= hi || (l < mid && a[l] <= a[r]) {
            merged.push(a[l]);
            l += 1;
        } else {
            merged.push(a[r]);
            r += 1;
        }
    }
    a[lo..hi].copy_from_slice(&merged);
    count
}

impl Solution {
    pub fn reverse_pairs(nums: Vec<i32>) -> i32 {
        let mut a: Vec<i64> = nums.iter().map(|&x| x as i64).collect(); // i64: 2 * x can overflow i32
        let n = a.len();
        sort_count(&mut a, 0, n) as i32
    }
}

