object Solution {
  def reversePairs(nums: Array[Int]): Int = {
    val a = nums.map(_.toLong) // Long: 2 * x can overflow Int

    // sorts a[lo, hi) and counts pairs i < j inside it with a(i) > 2 * a(j)
    def sortCount(lo: Int, hi: Int): Int = {
      if (hi - lo <= 1) {
        0
      } else {
        val mid = (lo + hi) / 2
        var count = sortCount(lo, mid) + sortCount(mid, hi)
        var p = mid // right values a[mid, p) are small enough for the current left value; p only moves forward
        for (i <- lo until mid) {
          while (p < hi && a(i) > 2 * a(p)) p += 1
          count += p - mid
        }
        // merge the two sorted halves
        val merged = new Array[Long](hi - lo)
        var l = lo
        var r = mid
        var k = 0
        while (l < mid || r < hi) {
          if (r >= hi || (l < mid && a(l) <= a(r))) {
            merged(k) = a(l)
            l += 1
          } else {
            merged(k) = a(r)
            r += 1
          }
          k += 1
        }
        System.arraycopy(merged, 0, a, lo, merged.length)
        count
      }
    }

    sortCount(0, a.length)
  }
}

