import "strconv"

func diffWaysToCompute(expression string) []int {
	memo := map[string][]int{} // sub-expression -> every value it can have
	var solve func(s string) []int
	solve = func(s string) []int {
		if r, ok := memo[s]; ok {
			return r
		}
		results := []int{}
		for i := 0; i < len(s); i++ {
			c := s[i]
			if c != '+' && c != '-' && c != '*' { // c is the last operator applied
				continue
			}
			for _, x := range solve(s[:i]) {
				for _, y := range solve(s[i+1:]) {
					switch c {
					case '+':
						results = append(results, x+y)
					case '-':
						results = append(results, x-y)
					default:
						results = append(results, x*y)
					}
				}
			}
		}
		if len(results) == 0 { // no operator: the expression is a single number
			n, _ := strconv.Atoi(s)
			results = append(results, n)
		}
		memo[s] = results
		return results
	}
	return solve(expression)
}

