            char c = expression[i];
            if (c != '+' && c != '-' && c != '*') continue;  // c is the last operator applied
            vector<int> lefts = diffWaysToCompute(expression.substr(0, i));
            vector<int> rights = diffWaysToCompute(expression.substr(i + 1));
            for (int x : lefts)
                for (int y : rights)
                    results.push_back(c == '+' ? x + y : c == '-' ? x - y : x * y);
        }
        if (results.empty()) results.push_back(stoi(expression));  // no operator: a single number
        memo[expression] = results;
        return results;
    }
};

