use std::collections::HashMap;

fn solve(s: &str, memo: &mut HashMap<String, Vec<i32>>) -> Vec<i32> {
    if let Some(r) = memo.get(s) {
        return r.clone();
    }
    let mut results = Vec::new();
    for (i, c) in s.char_indices() {
        if c != '+' && c != '-' && c != '*' {
            continue; // c is the last operator applied
        }
        let lefts = solve(&s[..i], memo);
        let rights = solve(&s[i + 1..], memo);
        for &x in &lefts {
            for &y in &rights {
                results.push(match c {
                    '+' => x + y,
                    '-' => x - y,
                    _ => x * y,
                });
            }
        }
    }
    if results.is_empty() {
        results.push(s.parse().unwrap()); // no operator: the expression is a single number
    }
    memo.insert(s.to_string(), results.clone());
    results
}

impl Solution {
    pub fn diff_ways_to_compute(expression: String) -> Vec<i32> {
        solve(&expression, &mut HashMap::new()) // memo: sub-expression -> every value it can have
    }
}

