import "sort"

func carPooling(trips [][]int, capacity int) bool {
	events := [][2]int{} // {position, change in the number of people}
	for _, t := range trips {
		events = append(events, [2]int{t[1], t[0]}, [2]int{t[2], -t[0]})
	}
	sort.Slice(events, func(i, j int) bool { // at the same position the drop-offs (negative) come first
		if events[i][0] != events[j][0] {
			return events[i][0] < events[j][0]
		}
		return events[i][1] < events[j][1]
	})
	load := 0
	for _, e := range events {
		load += e[1]
		if load > capacity {
			return false
		}
	}
	return true
}

