object Solution {
  def carPooling(trips: Array[Array[Int]], capacity: Int): Boolean = {
    // (position, change in the number of people)
    val events = trips.flatMap(t => Array((t(1), t(0)), (t(2), -t(0))))
    val sorted = events.sorted // at the same position the drop-offs (negative) come first
    var load = 0
    var i = 0
    while (i < sorted.length) {
      load += sorted(i)._2
      if (load > capacity) return false
      i += 1
    }
    true
  }
}

