func (this *MyCalendarTwo) Book(start int, end int) bool {
	this.delta[start]++
	this.delta[end]--
	times := make([]int, 0, len(this.delta))
	for t := range this.delta {
		times = append(times, t)
	}
	sort.Ints(times)
	active := 0
	for _, t := range times {
		active += this.delta[t]
		if active >= 3 { // a triple booking: undo the two changes
			this.delta[start]--
			this.delta[end]++
			return false
		}
	}
	return true
}

