class MyCalendarTwo {
    map<int, int> delta;  // time -> change in the number of active events (+1 at a start, -1 at an end); sorted by time

public:
    MyCalendarTwo() {}

    bool book(int start, int end) {
        delta[start]++;
        delta[end]--;
        int active = 0;
        for (auto& [t, change] : delta) {
            active += change;
            if (active >= 3) {  // a triple booking: undo the two changes
                delta[start]--;
