    }

    fn book(&mut self, start: i32, end: i32) -> bool {
        *self.delta.entry(start).or_insert(0) += 1;
        *self.delta.entry(end).or_insert(0) -= 1;
        let mut active = 0;
        for change in self.delta.values() {
            active += change;
            if active >= 3 { // a triple booking: undo the two changes
                *self.delta.get_mut(&start).unwrap() -= 1;
                *self.delta.get_mut(&end).unwrap() += 1;
                return false;
            }
        }
        true
    }
}

