class MyCalendarTwo() {
  // time -> change in the number of active events (+1 at a start, -1 at an end); sorted by time
  private val delta = scala.collection.mutable.TreeMap[Int, Int]()

  def book(start: Int, end: Int): Boolean = {
    delta(start) = delta.getOrElse(start, 0) + 1
    delta(end) = delta.getOrElse(end, 0) - 1
    var active = 0
    var ok = true
    val it = delta.valuesIterator
    while (ok && it.hasNext) {
      active += it.next()
      if (active >= 3) ok = false // a triple booking
    }
    if (!ok) { // undo the two changes
      delta(start) = delta(start) - 1
      delta(end) = delta(end) + 1
    }
    ok
  }
}

