import "sort"

func rectangleArea(rectangles [][]int) int {
	const mod = 1_000_000_007
	var xs []int
	for _, r := range rectangles {
		xs = append(xs, r[0], r[2])
	}
	sort.Ints(xs)
	n := 0
	for i, x := range xs {
		if i == 0 || x != xs[i-1] {
			xs[n] = x
			n++
		}
	}
	xs = xs[:n]

	total := 0
	for k := 0; k+1 < len(xs); k++ { // between two neighbouring x values the picture does not change
		left, right := xs[k], xs[k+1]
		// the y-spans of the rectangles that cover the whole strip, merged from the bottom up
		var spans [][2]int
		for _, r := range rectangles {
			if r[0] <= left && r[2] >= right {
				spans = append(spans, [2]int{r[1], r[3]})
			}
		}
		sort.Slice(spans, func(i, j int) bool { return spans[i][0] < spans[j][0] })
		covered := 0
		end := -1 // top of the last counted span (coordinates are >= 0)
		for _, s := range spans {
			if s[0] > end {
				covered += s[1] - s[0]
				end = s[1]
			} else if s[1] > end {
				covered += s[1] - end
				end = s[1]
			}
		}
		total = (total + covered*(right-left)) % mod // covered * width stays below 2^63
	}
	return total
}

