class Solution {
public:
    int rectangleArea(vector<vector<int>>& rectangles) {
        const long long MOD = 1000000007;
        vector<int> xs;
        for (auto& r : rectangles) {
            xs.push_back(r[0]);
            xs.push_back(r[2]);
        }
        sort(xs.begin(), xs.end());
        xs.erase(unique(xs.begin(), xs.end()), xs.end());

        long long total = 0;
        for (int k = 0; k + 1 < (int)xs.size(); k++) {  // between two neighbouring x values the picture does not change
            int left = xs[k], right = xs[k + 1];
            // the y-spans of the rectangles that cover the whole strip, merged from the bottom up
            vector<pair<int, int>> spans;
            for (auto& r : rectangles)
                if (r[0] <= left && r[2] >= right) spans.push_back({r[1], r[3]});
            sort(spans.begin(), spans.end());
            long long covered = 0;
            int end = -1;  // top of the last counted span (coordinates are >= 0)
            for (auto& [lo, hi] : spans) {
                if (lo > end) {
                    covered += hi - lo;
                    end = hi;
                } else if (hi > end) {
                    covered += hi - end;
                    end = hi;
                }
            }
            total = (total + covered * (right - left)) % MOD;  // covered * width stays below 2^63
        }
        return (int)total;
    }
};

