import (
	"math"
	"sort"
)

func removeCoveredIntervals(intervals [][]int) int {
	ordered := make([][]int, len(intervals))
	copy(ordered, intervals)
	// start ascending; for equal starts the longer interval first, so it covers the shorter one
	sort.Slice(ordered, func(i, j int) bool {
		if ordered[i][0] != ordered[j][0] {
			return ordered[i][0] < ordered[j][0]
		}
		return ordered[i][1] > ordered[j][1]
	})
	remaining := 0
	maxEnd := math.MinInt
	for _, iv := range ordered {
		if iv[1] > maxEnd { // reaches further than everything before it: not covered
			remaining++
			maxEnd = iv[1]
		}
	}
	return remaining
}

