import "sort"

func employeeFreeTime(schedule [][][]int) [][]int {
	// merge everyone's working intervals into one list sorted by start
	everyone := [][]int{}
	for _, emp := range schedule {
		everyone = append(everyone, emp...)
	}
	sort.Slice(everyone, func(i, j int) bool { return everyone[i][0] < everyone[j][0] })

	free := [][]int{}
	if len(everyone) == 0 {
		return free
	}
	end := everyone[0][1] // latest end seen so far
	for _, iv := range everyone[1:] {
		if iv[0] > end {
			free = append(free, []int{end, iv[0]}) // nobody is working between end and iv[0]
		}
		if iv[1] > end {
			end = iv[1]
		}
	}
	return free
}

