        }
        sort(everyone.begin(), everyone.end());

        vector<vector<int>> free;
        if (everyone.empty()) return free;
        int end = everyone[0][1];  // latest end seen so far
        for (int i = 1; i < (int)everyone.size(); i++) {
            if (everyone[i][0] > end) {
                free.push_back({end, everyone[i][0]});  // nobody is working in between
            }
            end = max(end, everyone[i][1]);
        }
        return free;
    }
};

