def count_primes(n: int) -> int:
    if n < 3:
        return 0
    is_prime = bytearray([1]) * n  # is_prime[k] == 1 until k is crossed out
    is_prime[0] = is_prime[1] = 0
    i = 2
    while i * i < n:
        if is_prime[i]:
            # cross out the multiples of i, starting at i * i (smaller ones were crossed out already)
            is_prime[i * i::i] = bytes(len(range(i * i, n, i)))
        i += 1
    return is_prime.count(1)

