    pub fn count_primes(n: i32) -> i32 {
        if n < 3 {
            return 0;
        }
        let n = n as usize;
        let mut composite = vec![false; n]; // composite[k] is true once k is crossed out
        let mut i = 2;
        while i * i < n {
            if !composite[i] {
                // cross out the multiples of i, starting at i*i (smaller ones were crossed out already)
                let mut j = i * i;
                while j < n {
                    composite[j] = true;
                    j += i;
                }
            }
            i += 1;
        }
        (2..n).filter(|&k| !composite[k]).count() as i32
    }
