    ugly = [1]
    i2 = i3 = i5 = 0  # next ugly number to multiply by 2, 3 and 5
    while len(ugly) < n:
        a, b, c = ugly[i2] * 2, ugly[i3] * 3, ugly[i5] * 5
        nxt = min(a, b, c)
        ugly.append(nxt)
        # advance every pointer that produced nxt, so duplicates (like 6 = 2*3 = 3*2) are added once
        if nxt == a:
            i2 += 1
        if nxt == b:
            i3 += 1
        if nxt == c:
            i5 += 1
    return ugly[n - 1]

