import "strconv"

func fractionToDecimal(numerator int, denominator int) string {
	if numerator == 0 {
		return "0"
	}
	negative := (numerator < 0) != (denominator < 0)
	num, den := absFrac(numerator), absFrac(denominator) // Go's int is 64-bit, so abs(-2^31) is safe
	out := ""
	if negative {
		out = "-"
	}
	out += strconv.Itoa(num / den)
	rem := num % den
	if rem == 0 {
		return out
	}
	out += "."
	seen := map[int]int{} // remainder -> position in out where its digit starts
	for rem != 0 {
		if at, ok := seen[rem]; ok { // same remainder again: the digits from there on repeat
			return out[:at] + "(" + out[at:] + ")"
		}
		seen[rem] = len(out)
		rem *= 10
		out += strconv.Itoa(rem / den)
		rem %= den
	}
	return out
}

func absFrac(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

