use std::collections::HashMap;

impl Solution {
    pub fn fraction_to_decimal(numerator: i32, denominator: i32) -> String {
        if numerator == 0 {
            return "0".to_string();
        }
        let negative = (numerator < 0) != (denominator < 0);
        // i64: abs(-2^31) does not fit in an i32
        let (num, den) = ((numerator as i64).abs(), (denominator as i64).abs());
        let mut out = String::new();
        if negative {
            out.push('-');
        }
        out.push_str(&(num / den).to_string());
        let mut rem = num % den;
        if rem == 0 {
            return out;
        }
        out.push('.');
        let mut seen: HashMap<i64, usize> = HashMap::new(); // remainder -> position in out where its digit starts
        while rem != 0 {
            if let Some(&at) = seen.get(&rem) {
                // same remainder again: the digits from there on repeat
                return format!("{}({})", &out[..at], &out[at..]);
            }
            seen.insert(rem, out.len());
            rem *= 10;
            out.push_str(&(rem / den).to_string());
            rem %= den;
        }
        out
    }
}

