    var y = 0
    var d = 0
    for (c <- instructions) {
      if (c == 'G') {
        x += dx(d)
        y += dy(d)
      } else if (c == 'L') {
        d = (d + 3) % 4
      } else {
        d = (d + 1) % 4
      }
    }
    // after one pass: back at the start, or not facing north (four passes then bring it home)
    (x == 0 && y == 0) || d != 0
  }
}

