import "strings"

func fullJustify(words []string, maxWidth int) []string {
	lines := []string{}
	i := 0
	for i < len(words) {
		// take words i..j-1: their letters plus one space between each pair must fit
		j, letters := i, 0
		for j < len(words) && letters+len(words[j])+(j-i) <= maxWidth {
			letters += len(words[j])
			j++
		}
		gaps := j - i - 1
		var line string
		if j == len(words) || gaps == 0 { // the last line, or a single word: left-justified
			line = strings.Join(words[i:j], " ")
			line += strings.Repeat(" ", maxWidth-len(line))
		} else {
			base, extra := (maxWidth-letters)/gaps, (maxWidth-letters)%gaps // the first `extra` gaps get one more space
			var sb strings.Builder
			for k := i; k < j; k++ {
				sb.WriteString(words[k])
				if k < j-1 {
					n := base
					if k-i < extra {
						n++
					}
					sb.WriteString(strings.Repeat(" ", n))
				}
			}
			line = sb.String()
		}
		lines = append(lines, line)
		i = j
	}
	return lines
}

