def codec(strs: list[str]) -> list[str]:
    def encode(items: list[str]) -> str:
        # length, "#", then the text itself: ["ab", ""] -> "2#ab0#"
        return "".join(str(len(s)) + "#" + s for s in items)

    def decode(text: str) -> list[str]:
        out = []
        i = 0
        while i < len(text):
            hash_pos = text.index("#", i)
            length = int(text[i:hash_pos])
            out.append(text[hash_pos + 1 : hash_pos + 1 + length])
            i = hash_pos + 1 + length  # jump over exactly `length` characters
        return out

    return decode(encode(strs))

