import "strings"

func codec(strs []string) []string {
	// length, "#", then the text itself: ["ab", ""] -> "2#ab0#"
	var sb strings.Builder
	for _, s := range strs {
		sb.WriteString(strconv.Itoa(len(s)))
		sb.WriteByte('#')
		sb.WriteString(s)
	}
	text := sb.String()

	out := []string{}
	i := 0
	for i < len(text) {
		hashPos := i + strings.IndexByte(text[i:], '#')
		length, _ := strconv.Atoi(text[i:hashPos])
		out = append(out, text[hashPos+1:hashPos+1+length])
		i = hashPos + 1 + length // jump over exactly `length` bytes
	}
	return out
}

