object Solution {
  def codec(strs: Array[String]): Array[String] = {
    // length, "#", then the text itself: ["ab", ""] -> "2#ab0#"
    val sb = new StringBuilder()
    for (s <- strs) {
      sb.append(s.length).append('#').append(s)
    }
    val text = sb.toString

    val out = scala.collection.mutable.ArrayBuffer[String]()
    var i = 0
    while (i < text.length) {
      val hashPos = text.indexOf('#', i)
      val length = text.substring(i, hashPos).toInt
      out += text.substring(hashPos + 1, hashPos + 1 + length)
      i = hashPos + 1 + length // jump over exactly `length` characters
    }
    out.toArray
  }
}

